# ----------------------------------------------------------------------------
#  WORLD CONSTANTS
# ----------------------------------------------------------------------------
CS = 16                 # chunk width / depth
WH = 128                # world height
NSEC = WH // 16         # 16x16x16 sections per chunk
SEA = 63                # sea level (top water block)
CS2 = CS * CS
CVOL = CS2 * WH
DAY_LEN = 1200.0        # 20 minute days, like the real game


def clamp(v, a, b):
    return a if v < a else b if v > b else v


def lerp(a, b, t):
    return a + (b - a) * t


# ----------------------------------------------------------------------------
#  BLOCK REGISTRY
#  shape: none cube cross liquid torch slab stairs door ladder fence crop snow
#         cactus bed farmland
# ----------------------------------------------------------------------------
BLOCKS = []
_BN = {}


def _blk(bid, name, shape='cube', tex=None, hard=1.0, tool=None, tier=-1, drop=None, light=0, cut=None,
         opaque=None, solid=None, tint=None, sound='stone', falls=False, support=None, repl=False, trans=False,
         front=None, fuel=0.0):
    assert bid == len(BLOCKS), (bid, name)
    if isinstance(tex, str):
        tex = (tex, tex, tex)
    if opaque is None:
        opaque = shape == 'cube' and not trans
    if solid is None:
        solid = shape not in ('none', 'cross', 'liquid', 'torch', 'crop', 'snow', 'ladder', 'fire', 'portal', 'endportal')
    if cut is None:
        cut = 15 if opaque else 0
    d = dict(id=bid, name=name, shape=shape, tex=tex, hard=hard, tool=tool, tier=tier, drop=drop, light=light,
             cut=cut, opaque=opaque, solid=solid, tint=tint, sound=sound, falls=falls, support=support, repl=repl,
             trans=trans, front=front, fuel=fuel)
    BLOCKS.append(d)
    _BN[name] = bid
    return bid


