ITEMS = {}
_IN = {}


def _item(iid, name, tile, stack=64, **k):
    d = dict(id=iid, name=name, tile=tile, stack=stack)
    d.update(k)
    ITEMS[iid] = d
    _IN[name] = iid
    return iid


