def creative_tab(i):
    """The creative tab an item / block belongs in (None: not in the creative inventory at all)."""
    if i in CTAB_EXTRA:
        return CTAB_EXTRA[i]
    if i < 256:
        if i in (B_AIR, B_WATER, B_LAVA, B_FIRE, B_PORTAL, B_DOOR, B_DOOR_TOP, B_BED, B_BED_HEAD, B_WHEAT,
                 B_FURNACE_LIT, B_DSLAB, B_FARMLAND, B_CANE, B_NETHER_WART, B_END_PORTAL):
            return None
        if i in (B_WIRE, B_RTORCH_OFF, B_REPEATER, B_REPEATER_ON, B_PISTON_HEAD, B_LAMP_ON, B_IRON_DOOR,
                 B_IRON_DOOR_TOP, B_REDSTONE_ORE_LIT):
            return None
        if i in (B_TNT, B_RTORCH_ON, B_LEVER, B_BUTTON, B_PLATE_STONE, B_PLATE_WOOD, B_PISTON, B_STICKY_PISTON,
                 B_LAMP, B_NOTE, B_DISPENSER):
            return 'redstone'
        if i in RAILS:
            return 'transport'
        if i in (B_ROSE, B_DANDELION, B_TALLGRASS, B_FERN, B_DEADBUSH, B_CACTUS, B_MUSH_BROWN, B_MUSH_RED, B_SAPLING, B_WEB,
                 B_LEAVES, B_BIRCH_LEAVES, B_SPRUCE_LEAVES, B_TORCH, B_LADDER, B_FENCE, B_NETHER_FENCE, B_TABLE,
                 B_FURNACE, B_CHEST, B_SNOW_LAYER, B_JACK, B_PUMPKIN, B_BOOKSHELF, B_SPAWNER, B_ENCH_TABLE,
                 B_END_FRAME, B_DRAGON_EGG):
            return 'deco'
        return 'building'
    it = ITEMS[i]
    if it.get('ctab'):
        return it['ctab']
    if i == I_DOOR:
        return 'redstone'
    if i == I_BOAT:
        return 'transport'
    if it.get('food'):
        return 'food'
    if it.get('tool') in ('pick', 'axe', 'shovel', 'hoe') or i in (I_FLINT_STEEL, I_SHEARS):
        return 'tools'
    if it.get('tool') == 'sword' or it.get('armor') is not None or i in (I_BOW, I_ARROW):
        return 'combat'
    if i in (I_BUCKET, I_WATER_BUCKET, I_LAVA_BUCKET, I_SNOWBALL, I_PAPER, I_BOOK, I_BED, I_BOWL) or i in SPAWN_EGGS:
        return 'misc'
    return 'materials'


def creative_list(tab, search=''):
    ids = [b for b in range(1, NBLOCKS)] + sorted(ITEMS)
    if tab == 'search':
        q = search.strip().lower()
        return [i for i in ids if creative_tab(i) and (not q or q in item_name(i).lower())]
    return [i for i in ids if creative_tab(i) == tab]


