def fw_colors(v, fade=False):
    """The colours (wool / dye numbers) in a firework star or rocket's value (or its fade colours)."""
    m = (v >> (32 if fade else 16)) & 0xFFFF
    return [k for k in range(16) if m >> k & 1]


def firework_craft(stacks):
    """Shapeless firework crafting - what you put in decides what comes out:
    gunpowder + dyes (+ a fire charge: large ball, a gold nugget: star, a feather: burst; + a diamond: trail;
    + glowstone dust: twinkle) -> a firework star;  a star + dyes -> it fades to those colours;
    paper + 1-3 gunpowder (+ up to 7 stars) -> 3 rockets that fly 1-3 long.  -> (item, count, value) or None"""
    st = [s for s in stacks if s]
    ids = [s[0] for s in st]
    if not ids:
        return None
    dyes = [DYE_COLOR[i] for i in ids if i in DYE_COLOR]
    if ids.count(I_PAPER) == 1 and 1 <= ids.count(I_GUNPOWDER) <= 3 and ids.count(I_FIREWORK_STAR) <= 7 and \
            all(i in (I_PAPER, I_GUNPOWDER, I_FIREWORK_STAR) for i in ids):
        v = ids.count(I_GUNPOWDER)
        for s in st:
            if s[0] == I_FIREWORK_STAR:
                v |= s[2] & FW_STAR_BITS
        return (I_FIREWORK, 3, v)
    if ids.count(I_GUNPOWDER) == 1 and dyes and all(i == I_GUNPOWDER or i in DYE_COLOR or i in FW_MODS or
                                                     i in (I_DIAMOND, I_GLOWSTONE_DUST) for i in ids):
        shapes = [FW_MODS[i] for i in ids if i in FW_MODS]
        if len(shapes) > 1 or ids.count(I_DIAMOND) > 1 or ids.count(I_GLOWSTONE_DUST) > 1:
            return None
        v = 1 << (8 + (shapes[0] if shapes else 0))
        if I_DIAMOND in ids:
            v |= FW_TRAIL
        if I_GLOWSTONE_DUST in ids:
            v |= FW_TWINKLE
        for c in dyes:
            v |= 1 << (16 + c)
        return (I_FIREWORK_STAR, 1, v)
    if ids.count(I_FIREWORK_STAR) == 1 and dyes and all(i == I_FIREWORK_STAR or i in DYE_COLOR for i in ids):
        v = [s for s in st if s[0] == I_FIREWORK_STAR][0][2]
        for c in dyes:
            v |= 1 << (32 + c)
        return (I_FIREWORK_STAR, 1, v)
    return None


def firework_lines(st):
    """Tooltip lines for a firework rocket / star."""
    if not st or st[0] not in FIREWORK_ITEMS:
        return []
    v = st[2]
    out = ['Flight Duration: %d' % max(1, v & 3)] if st[0] == I_FIREWORK else []
    shapes = [FW_SHAPES[k] for k in range(4) if v >> (8 + k) & 1]
    if shapes:
        out.append(', '.join(shapes))
    if fw_colors(v):
        out.append(', '.join(WOOL_NAMES[c] for c in fw_colors(v)))
    if fw_colors(v, True):
        out.append('Fade to ' + ', '.join(WOOL_NAMES[c] for c in fw_colors(v, True)))
    if v & FW_TRAIL:
        out.append('Trail')
    if v & FW_TWINKLE:
        out.append('Twinkle')
    return out
