def _brews():
    P = POTION_ID
    water, awk = P[('water', '', False)], P[('awkward', '', False)]
    BREW[(water, I_NETHER_WART)] = awk
    for ing in (I_REDSTONE, I_SUGAR, I_GLISTER_MELON, I_SPIDER_EYE, I_GHAST_TEAR, I_BLAZE_POWDER, I_MAGMA_CREAM):
        BREW[(water, ing)] = P[('mundane', '', False)]
    BREW[(water, I_GLOWSTONE_DUST)] = P[('thick', '', False)]
    BREW[(water, I_FERMENTED_EYE)] = P[('weakness', '', False)]
    for ing, kind in ((I_SUGAR, 'swiftness'), (I_GLISTER_MELON, 'healing'), (I_BLAZE_POWDER, 'strength'),
                      (I_MAGMA_CREAM, 'fire_res'), (I_GHAST_TEAR, 'regen'), (I_GOLDEN_CARROT, 'night'),
                      (I_PUFFERFISH, 'water_breath'), (I_SPIDER_EYE, 'poison'), (I_SLIMEBALL, 'leaping')):
        BREW[(awk, ing)] = P[(kind, '', False)]
    for a, b in (('swiftness', 'slowness'), ('leaping', 'slowness'), ('fire_res', 'slowness'),
                 ('healing', 'harming'), ('poison', 'harming'), ('night', 'invis'), ('strength', 'weakness'),
                 ('regen', 'weakness')):                     # a fermented spider eye turns a potion bad
        for var in ('', 'x', '2'):
            for sp in (False, True):
                if (a, var, sp) in P:
                    BREW[(P[(a, var, sp)], I_FERMENTED_EYE)] = P.get((b, var, sp)) or P[(b, '', sp)]
    for (kind, var, sp), it in P.items():
        if (kind, 'x', sp) in P and var != 'x':
            BREW[(it, I_REDSTONE)] = P[(kind, 'x', sp)]        # redstone: it lasts longer
        if (kind, '2', sp) in P and var != '2':
            BREW[(it, I_GLOWSTONE_DUST)] = P[(kind, '2', sp)]  # glowstone: it's stronger
        if not sp and (kind, var, True) in P:
            BREW[(it, I_GUNPOWDER)] = P[(kind, var, True)]     # gunpowder: a splash potion


_brews()

