def xp_cap(level):
    """Points from one level to the next (the 1.0 formula: 7, 10, 14, 17, 21...)."""
    return 7 + (level * 7 >> 1)


def xp_orb_value(n):
    """The biggest orb that fits in n points."""
    for v in XP_SPLITS:
        if n >= v:
            return v
    return 1
