FORTUNE_OK = {B_COAL_ORE, B_DIAMOND_ORE, B_GLOWSTONE, B_LAPIS_ORE}
SILK_OK.add(B_LAPIS_ORE)
SILK_OK.add(B_MELON)
SILK_OK.add(B_EMERALD_ORE)
FORTUNE_OK.add(B_EMERALD_ORE)
ORE_XP[B_EMERALD_ORE] = (3, 7)
SILK_OK.add(B_REDSTONE_ORE)
SILK_OK.add(B_ENDER_CHEST)
SILK_OK.add(B_QUARTZ_ORE)
SILK_OK.add(B_GLASS_PANE)
SILK_OK.update((B_MYCELIUM, B_MUSH_STEM, B_CAP_BROWN, B_CAP_RED))
FORTUNE_OK.add(B_QUARTZ_ORE)
ORE_XP[B_QUARTZ_ORE] = (2, 5)
FORTUNE_OK.update((B_REDSTONE_ORE, B_REDSTONE_ORE_LIT))


def block_drops(b, meta, rng, tool=None, silk=False, fortune=0):
    """What mining block b gives you -> list of (item, count).  silk: silk touch; fortune: its level (0-3)."""
    if silk and b == B_REDSTONE_ORE_LIT:
        return [(B_REDSTONE_ORE, 1)]
    if silk and b in SILK_OK:
        return [(b, 1)]
    out = _block_drops(b, meta, rng, tool)
    if fortune and b in FORTUNE_OK and out:
        extra = max(0, rng.randint(0, fortune + 1) - 1)          # the real game's ore bonus: x2..x(fortune+1)
        out = [(it, n * (extra + 1)) for it, n in out]
    return out


def _block_drops(b, meta, rng, tool=None):
    d = BLOCKS[b]['drop']
    if d is None:
        return [(b, 1)] if b not in (B_DOOR_TOP, B_BED_HEAD) else []
    if isinstance(d, int):
        return [(d, 1)]
    if d == 'none':
        return []
    if d == 'leaves':
        if tool == 'shears':
            return [(b, 1)]
        out = []
        if rng.random() < (0.025 if b == B_JUNGLE_LEAVES else 0.05):
            out.append((B_SAPLING, 1))
        if b == B_LEAVES and rng.random() < 0.01:
            out.append((I_APPLE, 1))
        return out
    if d == 'gravel':
        return [(I_FLINT, 1)] if rng.random() < 0.1 else [(B_GRAVEL, 1)]
    if d == 'tallgrass':
        return [(I_SEEDS, 1)] if rng.random() < 0.125 else []
    if d == 'deadbush':
        n = rng.randint(0, 2)
        return [(I_STICK, n)] if n else []
    if d == 'cane':
        return [(I_CANE, 1)]
    if d == 'clay':
        return [(I_CLAY, 4)]
    if d == 'bookshelf':
        return [(I_BOOK, 3)]
    if d == 'wheat':
        if meta >= 7:
            return [(I_WHEAT, 1), (I_SEEDS, rng.randint(1, 3))]
        return [(I_SEEDS, 1)]
    if d == 'carrots':
        return [(I_CARROT, rng.randint(1, 4) if meta >= 7 else 1)]
    if d == 'potatoes':
        if meta < 7:
            return [(I_POTATO, 1)]
        return [(I_POTATO, rng.randint(1, 4))] + ([(I_POISON_POTATO, 1)] if rng.random() < 0.02 else [])
    if d == 'melon':
        return [(I_MELON_SLICE, rng.randint(3, 7))]
    if d == 'emerald':
        return [(I_EMERALD, 1)]
    if d == 'brewing':
        return [(I_BREWING_STAND, 1)]
    if d == 'cauldron':
        return [(I_CAULDRON, 1)]
    if d == 'anvil':
        return [(I_ANVIL, 1)]
    if d == 'sign':
        return [(I_SIGN, 1)]
    if d == 'vine':
        return [(B_VINE, 1)] if tool == 'shears' else []
    if d == 'cocoa':
        return [(DYES[12], 3 if (meta >> 2) >= 2 else 1)]
    if d == 'hook':
        return [(I_TRIPWIRE_HOOK, 1)]
    if d == 'skull':
        return [(I_WITHER_SKULL, 1)]
    if d == 'echest':
        return [(B_OBSIDIAN, 8)]                         # (silk touch keeps it whole)
    if d == 'hopper':
        return [(I_HOPPER, 1)]
    if d == 'comparator':
        return [(I_COMPARATOR, 1)]
    if d == 'capbrown':                                  # a huge mushroom's cap: now and then a mushroom or two
        return [(B_MUSH_BROWN, max(0, rng.randint(0, 9) - 7))]
    if d == 'capred':
        return [(B_MUSH_RED, max(0, rng.randint(0, 9) - 7))]
    if d == 'quartz':
        return [(I_QUARTZ, 1)]
    if d == 'tripwire':
        return [(I_STRING, 1)]
    if d == 'mstem':
        return [(I_MELON_SEEDS, 1)]
    if d == 'pstem':
        return [(I_PUMPKIN_SEEDS, 1)]
    if d == 'door':
        return [(I_DOOR, 1)] if b == B_DOOR else []
    if d == 'irondoor':
        return [(I_IRON_DOOR, 1)] if b == B_IRON_DOOR else []
    if d == 'redstone':
        return [(I_REDSTONE, rng.randint(4, 5))]
    if d == 'wire':
        return [(I_REDSTONE, 1)]
    if d == 'repeater':
        return [(I_REPEATER, 1)]
    if d == 'bed':
        return [(I_BED, 1)] if b == B_BED else []
    if d == 'dslab':
        return [(B_SLAB, 2)]
    if d == 'ice':
        return []
    if d == 'snowball':                                   # one snowball per layer
        return [(I_SNOWBALL, (meta & 7) + 1)] if tool == 'shovel' else []
    if d == 'coal':
        return [(I_COAL, 1)]
    if d == 'lapis':
        return [(I_LAPIS, rng.randint(4, 8))]
    if d == 'web':                                        # string - but only if cut with a sword or shears
        return [(I_STRING, 1)] if tool in ('sword', 'shears') else []
    if d == 'diamond':
        return [(I_DIAMOND, 1)]
    if d == 'glowstone':
        return [(I_GLOWSTONE_DUST, rng.randint(2, 4))]
    if d == 'wart':
        return [(I_NETHER_WART, rng.randint(2, 4) if meta >= 3 else 1)]
    return [(b, 1)]


