    def sleeper_rail(curve):
        t = new()
        wood, iron = (105, 78, 45, 255), (160, 160, 168, 255)
        if not curve:
            for y in (1, 5, 9, 13):
                rect(t, 1, y, 14, y + 1, sh(wood, R.uniform(0.85, 1.05)))
            for y in range(16):
                pix(t, 3, y, sh(iron, 1.1))
                pix(t, 4, y, sh(iron, 0.85))
                pix(t, 11, y, sh(iron, 1.1))
                pix(t, 12, y, sh(iron, 0.85))
        else:
            for y in range(16):
                for x in range(16):
                    d = math.hypot(x - 15.5, y - 15.5)
                    if int(d) in (4, 8, 12) and x % 4 < 2 and 2 < d < 15:
                        t[y][x] = sh(wood, R.uniform(0.85, 1.05))
            for y in range(16):
                for x in range(16):
                    d = math.hypot(x - 15.5, y - 15.5)
                    if 3.2 <= d < 4.9 or 11.2 <= d < 12.9:
                        t[y][x] = sh(iron, 1.1 if d % 1 < 0.5 else 0.85)
        return t
