    def icon(rows, col, half=False, empty=False, hl=(1, 1)):
        t = new()
        for y, row in enumerate(rows):
            for x, ch in enumerate(row):
                if ch == 'X':
                    c = (40, 20, 20, 255) if empty or (half and x > len(row) // 2 - (0 if len(row) % 2 else 1)) else col
                    if not empty and (y, x) == hl and not (half and x > 3):
                        c = (255, 220, 220, 255)
                    t[4 + y][4 + x] = c
        outline(t, (10, 10, 10, 255))
        return t
