        for ex in eye_x:
            rect(t, ex, eye_y, ex + eye_w - 1, eye_y + 1, eyes)
        if mouth:
            rect(t, mouth[0], mouth[1], mouth[2], mouth[3], mouth[4])
        if snout:
            rect(t, 5, 9, 10, 12, snout)
            pix(t, 6, 10, (90, 40, 40, 255))
            pix(t, 9, 10, (90, 40, 40, 255))
        return t
