        for y in range(16):
            for x in range(16):
                c = c1 if ((x // 4) + (y // 4)) % 2 == 0 else c2
                if x % 4 == 0 or y % 4 == 0:
                    c = line
                t[y][x] = sh(S_(c), R.uniform(0.93, 1.05))
        return t
