    def bottle(liquid=None, splash=False):
        t = new()
        glass, rim = (200, 220, 235, 150), (235, 245, 255, 220)
        cy, rx, ry = (10.5, 5.2, 4.6) if splash else (10.0, 4.6, 4.6)
        for y in range(16):
            for x in range(16):
                d = ((x - 7.5) / rx) ** 2 + ((y - cy) / ry) ** 2
                if d <= 1.0:
                    if liquid and y >= cy - ry * (0.2 if not splash else 0.35):
                        t[y][x] = sh(liquid + (255,), (1.2 if x < 7 and y < cy + 1 else 1.0) * RF.uniform(0.95, 1.05))
                    else:
                        t[y][x] = glass
                    if d > 0.72:
                        t[y][x] = rim if y < cy else sh(t[y][x], 0.8)
        nw = 1 if splash else 2
        for y in range(2 if not splash else 3, int(cy - ry) + 1):
            for x in range(8 - nw, 8 + nw):
                t[y][x] = glass if x in (8 - nw, 7 + nw) else (215, 230, 240, 120)
        rect(t, 8 - nw, 1 if not splash else 2, 7 + nw, 2 if not splash else 3, (140, 100, 55, 255))   # the cork
        if liquid:
            pix(t, 6, int(cy) - 1, (255, 255, 255, 255))           # a shine
        return t
