    cols = ((152, 150, 148), (128, 122, 116), (172, 162, 150), (108, 102, 96), (140, 124, 112), (160, 150, 142))
    for _ in range(18):
        cx, cy = RT.uniform(0, 16), RT.uniform(0, 16)
        rx, ry = RT.uniform(1.3, 2.4), RT.uniform(1.1, 2.0)
        col = RT.choice(cols)
        for y in range(int(cy - ry) - 1, int(cy + ry) + 2):
            for x in range(int(cx - rx) - 1, int(cx + rx) + 2):
                d = ((x + 0.5 - cx) / rx) ** 2 + ((y + 0.5 - cy) / ry) ** 2
                if d <= 1.0:
                    lx, ly = (x + 0.5 - cx) / rx, (y + 0.5 - cy) / ry
                    shade = 1.12 if (lx + ly) < -0.5 else (0.8 if (lx + ly) > 0.6 else 1.0)
