    # ores: chunky nuggets with a bright corner and a dark edge
    def ore2(col, hi=None, lo=None, n=4):
        t = copy(stone)
        hi = hi or tuple(min(255, int(c * 1.3) + 20) for c in col)
        lo = lo or tuple(int(c * 0.55) for c in col)
        spots = []
        while len(spots) < n:
            cx, cy = RT.randrange(2, 13), RT.randrange(2, 13)
            if all(abs(cx - a) + abs(cy - b) > 5 for a, b in spots):
                spots.append((cx, cy))
        for cx, cy in spots:
            blob = {(cx + dx, cy + dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1)
                    if not (abs(dx) == 1 and abs(dy) == 1 and RT.random() < 0.6)}
            if RT.random() < 0.5:
                blob.add((cx + RT.choice((-2, 2)), cy))
            for (x, y) in blob:
                t[y][x] = sh(col + (255,), RT.uniform(0.9, 1.08))
            for (x, y) in blob:                              # dark edge below / right, highlight up / left
                if (x + 1, y) not in blob and 0 <= x + 1 < 16:
                    t[y][x + 1] = sh(lo + (255,), 1.0)
                if (x, y + 1) not in blob and 0 <= y + 1 < 16:
                    t[y + 1][x] = sh(lo + (255,), 1.0)
            tx, ty = min(blob, key=lambda p: p[0] + p[1])
            t[ty][tx] = hi + (255,)
        return t
