def gl_load():
    lib = ctypes.windll.opengl32
    g = globals()
    for name, res, args in _GL_FUNCS:
        fn = getattr(lib, name)
        fn.restype = res
        fn.argtypes = args
        g[name] = fn


def fvec(*v):
    return (ctypes.c_float * len(v))(*v)


class PIXELFORMATDESCRIPTOR(ctypes.Structure):
    _fields_ = ([('nSize', wt.WORD), ('nVersion', wt.WORD), ('dwFlags', wt.DWORD), ('iPixelType', ctypes.c_ubyte),
                 ('cColorBits', ctypes.c_ubyte)] +
                [(n, ctypes.c_ubyte) for n in ('cRedBits', 'cRedShift', 'cGreenBits', 'cGreenShift', 'cBlueBits',
                                               'cBlueShift', 'cAlphaBits', 'cAlphaShift', 'cAccumBits',
                                               'cAccumRedBits', 'cAccumGreenBits', 'cAccumBlueBits',
                                               'cAccumAlphaBits', 'cDepthBits', 'cStencilBits', 'cAuxBuffers',
                                               'iLayerType', 'bReserved')] +
                [('dwLayerMask', wt.DWORD), ('dwVisibleMask', wt.DWORD), ('dwDamageMask', wt.DWORD)])


class POINT(ctypes.Structure):
    _fields_ = [('x', ctypes.c_long), ('y', ctypes.c_long)]


class RECT(ctypes.Structure):
    _fields_ = [('left', ctypes.c_long), ('top', ctypes.c_long), ('right', ctypes.c_long), ('bottom', ctypes.c_long)]


class BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [('biSize', wt.DWORD), ('biWidth', ctypes.c_long), ('biHeight', ctypes.c_long), ('biPlanes', wt.WORD),
                ('biBitCount', wt.WORD), ('biCompression', wt.DWORD), ('biSizeImage', wt.DWORD),
                ('biXPelsPerMeter', ctypes.c_long), ('biYPelsPerMeter', ctypes.c_long), ('biClrUsed', wt.DWORD),
                ('biClrImportant', wt.DWORD)]


