class GLContext:
    """WGL OpenGL context on a Tk frame's native window."""

    def __init__(self, hwnd, software=False):
        self.hwnd = hwnd
        self.hdc = user32.GetDC(hwnd)
        pfd = PIXELFORMATDESCRIPTOR()
        pfd.nSize = ctypes.sizeof(PIXELFORMATDESCRIPTOR)
        pfd.nVersion = 1
        pfd.dwFlags = 0x4 | 0x20 | 0x1
        pfd.cColorBits = 32
        pfd.cDepthBits = 24
        fmt = gdi32.ChoosePixelFormat(self.hdc, ctypes.byref(pfd))
        if software:                                    # test switch: Windows' own software OpenGL
            n = gdi32.DescribePixelFormat(self.hdc, 1, ctypes.sizeof(PIXELFORMATDESCRIPTOR), ctypes.byref(pfd))
            for i in range(1, n + 1):
                q = PIXELFORMATDESCRIPTOR()
                gdi32.DescribePixelFormat(self.hdc, i, ctypes.sizeof(PIXELFORMATDESCRIPTOR), ctypes.byref(q))
                if (q.dwFlags & 0x40) and not (q.dwFlags & 0x1000) and (q.dwFlags & 0x25) == 0x25 \
                        and q.cColorBits >= 24 and q.cDepthBits >= 16:
                    fmt, pfd = i, q
                    break
        if not fmt or not gdi32.SetPixelFormat(self.hdc, fmt, ctypes.byref(pfd)):
            raise RuntimeError('This PC could not set up an OpenGL pixel format.')
        wgl = ctypes.windll.opengl32
        wgl.wglCreateContext.restype = ctypes.c_void_p
        wgl.wglCreateContext.argtypes = [wt.HDC]
        wgl.wglMakeCurrent.argtypes = [wt.HDC, ctypes.c_void_p]
        wgl.wglGetProcAddress.restype = ctypes.c_void_p
        wgl.wglGetProcAddress.argtypes = [ctypes.c_char_p]
        self.ctx = wgl.wglCreateContext(self.hdc)
        if not self.ctx or not wgl.wglMakeCurrent(self.hdc, self.ctx):
            raise RuntimeError('This PC could not create an OpenGL context.')
        self.wgl = wgl
        gl_load()
        self.vendor = (glGetString(GL_VENDOR) or b'?').decode('ascii', 'replace')
        self.renderer = (glGetString(GL_RENDERER) or b'?').decode('ascii', 'replace')
        self.version = (glGetString(GL_VERSION) or b'?').decode('ascii', 'replace')
        self.software = 'GDI Generic' in self.renderer
        self._swapint = None
        try:
            p = wgl.wglGetProcAddress(b'wglSwapIntervalEXT')
            if p:
                self._swapint = ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_int)(p)
        except Exception:
            self._swapint = None
        self.vsync = False
        self.set_vsync(True)

    def set_vsync(self, on):
        if self._swapint:
            try:
                self._swapint(1 if on else 0)
                self.vsync = bool(on)
            except Exception:
                self.vsync = False

    def swap(self):
        gdi32.SwapBuffers(self.hdc)


def make_texture(data, w, h, fmt=GL_RGBA, linear=False):
    tid = ctypes.c_uint(0)
    glGenTextures(1, ctypes.byref(tid))
    glBindTexture(GL_TEXTURE_2D, tid.value)
    f = GL_LINEAR if linear else GL_NEAREST
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, f)
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, f)
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP)
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP)
    glTexEnvi(GL_TEXTURE_ENV, GL_TEXTURE_ENV_MODE, GL_MODULATE)
    buf = ctypes.create_string_buffer(data, len(data)) if data is not None else None
    glTexImage2D(GL_TEXTURE_2D, 0, fmt, w, h, 0, fmt, GL_UNSIGNED_BYTE, buf)
    return tid.value


# ----------------------------------------------------------------------------
#  PIXEL FONT: a Windows font drawn into a texture once, then text is quads.
#  (Faster than glBitmap on integrated graphics, and it scales like the GUI.)
# ----------------------------------------------------------------------------
class PixelFont:
    CELL = 16

    def __init__(self, px=11, face='Tahoma'):
        self.tex = 0
        self.w = [6] * 256
        self.h = px
        dc = gdi32.CreateCompatibleDC(None)
        bmi = BITMAPINFOHEADER()
        bmi.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        bmi.biWidth, bmi.biHeight, bmi.biPlanes, bmi.biBitCount, bmi.biCompression = 256, -256, 1, 32, 0
        bits = ctypes.c_void_p()
        bmp = gdi32.CreateDIBSection(dc, ctypes.byref(bmi), 0, ctypes.byref(bits), None, 0)
        old_b = gdi32.SelectObject(dc, bmp)
        font = gdi32.CreateFontW(-px, 0, 0, 0, 400, 0, 0, 0, 0, 0, 0, 3, 0, face)      # 3 = no anti-aliasing
        old_f = gdi32.SelectObject(dc, font)
        gdi32.SetBkMode(dc, 1)
        gdi32.SetTextColor(dc, 0x00FFFFFF)
        for c in range(32, 256):
            gdi32.TextOutW(dc, (c % 16) * self.CELL + 1, (c // 16) * self.CELL + 1, chr(c), 1)
        widths = (ctypes.c_int * 256)()
        if gdi32.GetCharWidth32W(dc, 0, 255, widths):
            self.w = [int(v) + 1 for v in widths]
        raw = ctypes.string_at(bits, 256 * 256 * 4)
        out = bytearray(256 * 256 * 4)
        for i in range(256 * 256):
            v = raw[i * 4 + 2]
            if v:
                out[i * 4:i * 4 + 4] = b'\xff\xff\xff\xff'
        gdi32.SelectObject(dc, old_f)
        gdi32.SelectObject(dc, old_b)
        gdi32.DeleteObject(font)
        gdi32.DeleteObject(bmp)
        gdi32.DeleteDC(dc)
        self.data = bytes(out)

    def upload(self):
        self.tex = make_texture(self.data, 256, 256)

    def width(self, s, scale=1.0):
        w = self.w
        return sum(w[ord(c)] if ord(c) < 256 else w[63] for c in s) * scale

    def draw(self, s, x, y, scale, col, shadow=True):
        """Top-left at x, y in window pixels (ortho, y down).  Returns the width drawn."""
        if not s:
            return 0
        glEnable(GL_TEXTURE_2D)
        glBindTexture(GL_TEXTURE_2D, self.tex)
        pos, uv = array.array('f'), array.array('f')
        cx = x
        c = self.CELL / 256.0
        for ch in s:
            o = ord(ch)
            if o > 255:
                o = 63
            u, v = (o % 16) * c, (o // 16) * c
            x1, y1 = cx + self.CELL * scale, y + self.CELL * scale
            pos.extend((cx, y, x1, y, x1, y1, cx, y1))
            uv.extend((u, v, u + c, v, u + c, v + c, u, v + c))
            cx += self.w[o] * scale
        n = len(pos) // 2
        vp = (ctypes.c_float * len(pos)).from_buffer(pos)
        tp = (ctypes.c_float * len(uv)).from_buffer(uv)
        glEnableClientState(GL_VERTEX_ARRAY)
        glEnableClientState(GL_TEXTURE_COORD_ARRAY)
        glVertexPointer(2, GL_FLOAT, 0, vp)
        glTexCoordPointer(2, GL_FLOAT, 0, tp)
        if shadow:
            glPushMatrix()
            glTranslatef(scale, scale, 0)
            glColor4f(col[0] * 0.25, col[1] * 0.25, col[2] * 0.25, col[3] if len(col) > 3 else 1)
            glDrawArrays(GL_QUADS, 0, n)
            glPopMatrix()
        glColor4f(col[0], col[1], col[2], col[3] if len(col) > 3 else 1)
        glDrawArrays(GL_QUADS, 0, n)
        glDisableClientState(GL_VERTEX_ARRAY)
        glDisableClientState(GL_TEXTURE_COORD_ARRAY)
        glDisable(GL_TEXTURE_2D)
        return cx - x


# ----------------------------------------------------------------------------
#  SOUND: several waveOut streams at once (Windows mixes them), no files.
#  All sound synthesis runs in a worker process so startup stays fast.
# ----------------------------------------------------------------------------
class WAVEFORMATEX(ctypes.Structure):
    _fields_ = [('wFormatTag', wt.WORD), ('nChannels', wt.WORD), ('nSamplesPerSec', wt.DWORD),
                ('nAvgBytesPerSec', wt.DWORD), ('nBlockAlign', wt.WORD), ('wBitsPerSample', wt.WORD),
                ('cbSize', wt.WORD)]


class WAVEHDR(ctypes.Structure):
    pass


WAVEHDR._fields_ = [('lpData', ctypes.c_void_p), ('dwBufferLength', wt.DWORD), ('dwBytesRecorded', wt.DWORD),
                    ('dwUser', ctypes.c_size_t), ('dwFlags', wt.DWORD), ('dwLoops', wt.DWORD),
                    ('lpNext', ctypes.c_void_p), ('reserved', ctypes.c_size_t)]
SR = 22050


def liquid_sound(kind, n, f0, f1, vol, rnd):
    """n samples of running water ('babble': a soft rush with little bubbles), lava ('rumble': a deep churn with the
    odd low gloop) or being underwater ('deep': a dull, even hum, made to loop).  -> array('h')"""
    a1, a2 = {'babble': (0.16, 0.3), 'rumble': (0.03, 0.08), 'deep': (0.015, 0.04)}[kind]
    lp = lp2 = 0.0
    gain = gt = 0.6
    noise = [0.0] * n
    for i in range(n):
        lp += (rnd.uniform(-1, 1) - lp) * a1
        lp2 += (lp - lp2) * a2
        if i % 300 == 0:
            gt = rnd.uniform(0.25, 1.0)
        gain += (gt - gain) * 0.003
        noise[i] = lp2 * (1.0 if kind == 'deep' else gain)
    norm = 0.55 / (max(abs(v) for v in noise) or 1.0)
    extra = [0.0] * n
    tp = 2 * math.pi / SR
    if kind == 'deep':
        ph = 0.0
        for i in range(n):
            ph += (f0 + (f1 - f0) * i / n) * tp
            extra[i] = math.sin(ph) * 0.18
    else:
        rate, lo, hi, amp, glide = (24, 380.0, 1000.0, 0.3, 1.0006) if kind == 'babble' else (4, 70.0, 140.0, 0.5, 0.9996)
        for _ in range(int(n / SR * rate)):
            start = rnd.randrange(n)
            ln = int(SR * (rnd.uniform(0.012, 0.03) if kind == 'babble' else rnd.uniform(0.05, 0.09)))
            f, ph, a = rnd.uniform(lo, hi), 0.0, amp * rnd.uniform(0.5, 1.0)
            for j in range(min(ln, n - start)):
                ph += f * tp
                f *= glide
                extra[start + j] += math.sin(ph) * a * math.sin(math.pi * j / ln)
    out = array.array('h')
    fade = SR * 0.12
    for i in range(n):
        t = i / float(n)
        env = min(1.0, i / fade, (n - i) / fade) if kind == 'deep' else math.sin(math.pi * t) ** 0.8
        v = (noise[i] * norm + extra[i]) * env * vol * 1.8
        out.append(int((1 if v > 1 else -1 if v < -1 else v) * 28000))
    return out


def muffle_pcm(pcm):
    """A sound as heard underwater: the highs gone (two gentle low-pass poles, about 300 Hz)."""
    a = array.array('h')
    a.frombytes(pcm)
    out = array.array('h', bytes(len(a) * 2))
    l1 = l2 = 0.0
    for i, v in enumerate(a):
        l1 += (v - l1) * 0.09
        l2 += (l1 - l2) * 0.09
        s = int(l2 * 1.3)
        out[i] = 32767 if s > 32767 else (-32767 if s < -32767 else s)
    return out.tobytes()


def synth(parts, seed=7):
    """parts: (f0, f1, seconds, volume, kind).  Returns 16-bit mono PCM bytes."""
    out = array.array('h')
    rnd = random.Random(seed)
    for f0, f1, dur, vol, kind in parts:
        n = int(SR * dur)
        if kind in ('babble', 'rumble', 'deep'):
            out.extend(liquid_sound(kind, n, f0, f1, vol, rnd))
            continue
        ph = 0.0
        lp = 0.0
        two_pi_sr = 2 * math.pi / SR
        swell = kind in ('wail', 'hum')
        for i in range(n):
            t = i / float(n)
            ph += (f0 + (f1 - f0) * t) * two_pi_sr
            if swell:
                env = math.sin(math.pi * t) ** 0.8
            elif kind == 'rain':                           # (loops: quick fades, steady in between)
                env = min(1.0, i / (SR * 0.12), (n - i) / (SR * 0.12))
            else:
                env = (1 - t) ** 2 * (i / (SR * 0.003) if i < SR * 0.003 else 1.0)
            if kind == 'sine':
                s = math.sin(ph)
            elif kind == 'wail':                           # ghostly vibrato (ghasts)
                s = math.sin(ph + 0.9 * math.sin(i * 2 * math.pi * 5.5 / SR)) * 0.8 +                     math.sin(ph * 2.01) * 0.15
            elif kind == 'hum':                            # pulsing drone (portals)
                s = (math.sin(ph) + 0.6 * math.sin(ph * 1.5) + 0.3 * math.sin(ph * 2.02)) *                     (0.6 + 0.4 * math.sin(i * 2 * math.pi * 3.0 / SR)) * 0.55
            elif kind == 'crackle':                        # sparse pops (fire)
                s = rnd.uniform(-1, 1) if rnd.random() < 0.02 else s * 0.6 if i else 0.0
            elif kind == 'square':
                s = 0.5 if math.sin(ph) > 0 else -0.5
            elif kind == 'rain':                           # a steady hiss, with the odd drop landing close by
                lp += (rnd.uniform(-1, 1) - lp) * 0.3
                s = lp * 1.5 + (rnd.uniform(-0.8, 0.8) if rnd.random() < 0.003 else 0.0)
            elif kind == 'thunder':                        # a sharp crack, then a long low rolling rumble
                lp += (rnd.uniform(-1, 1) - lp) * (0.025 + 0.35 * max(0.0, 1.0 - t * 10))
                s = lp * (3.5 + 3.0 * math.sin(t * 19 + math.sin(t * 7) * 2.5) ** 2)
            elif kind == 'lnoise':
                lp += (rnd.uniform(-1, 1) - lp) * ((f0 + (f1 - f0) * t) / 4000.0)
                s = lp * 3.0
            else:
                s = rnd.uniform(-1, 1)
            v = s * env * vol
            out.append(int((1 if v > 1 else -1 if v < -1 else v) * 28000))
    return out.tobytes()


