class EnderDragon(Entity):
    """The boss of the end.  200 health; flies circles round the pillars, dives at players, heals from the ender
    crystals.  Only its head takes full damage - anywhere else takes a quarter (plus one), like the real game."""
    kind = 'dragon'
    hw, h = 2.0, 3.0
    maxhp = 200
    XP = 20000

    def __init__(self, x, y, z):
        Entity.__init__(self, x, y, z)
        self.hp = float(self.maxhp)
        self.state = 'circle'
        self.goal = (x, y, z)
        self.goal_t = 0.0
        self.ang = math.atan2(z, x)
        self.turn = random.choice((-1, 1))
        self.laps = 0
        self.speed = 10.0
        self.heal = None            # the crystal healing it (an entity id)
        self.heal_t = 0.0
        self.dying = 0.0            # seconds into its death (0 = alive)
        self.last_part = 'body'
        self.hit_cool = {}
        self.target_id = None
        self.charge_t = 0.0
        self.close = False
        self.growl_t = 4.0
        self.flap_t = 0.0
        self.break_t = 0.0
        self.xp_left = self.XP

    def parts(self):
        """Hit boxes in the world, [(name, box)] - it is far too long for one box."""
        yaw = math.radians(self.yaw)
        fx, fz = math.sin(yaw), -math.cos(yaw)
        rx, rz = -fz, fx
        x, y, z = self.x, self.y, self.z
        pd = -math.sin(math.radians(self.pitch))               # nose down: the head drops, the tail rises
        out = []

        def box(name, cx, cy, cz, hw, hh):
            out.append((name, (cx - hw, cy - hh, cz - hw, cx + hw, cy + hh, cz + hw)))
        box('body', x + fx * 1.2, y + 1.75, z + fz * 1.2, 1.6, 1.25)
        box('body', x - fx * 1.2, y + 1.75, z - fz * 1.2, 1.6, 1.25)
        box('neck', x + fx * 4.2, y + 2.2 + pd * 4.2, z + fz * 4.2, 0.7, 0.7)
        box('head', x + fx * 8.0, y + 2.45 + pd * 8.0, z + fz * 8.0, 1.1, 0.9)
        for s in (1, -1):
            box('wing', x + rx * 5.5 * s, y + 2.7, z + rz * 5.5 * s, 2.6, 0.6)
        for k in range(3):
            d = 4.6 + k * 2.2
            box('tail', x - fx * d, y + 1.8 - pd * d, z - fz * d, 0.7, 0.6)
        return out

    def ray_hit(self, ox, oy, oz, dx, dy, dz, maxd):
        best = None
        for name, b in self.parts():
            h = ray_box(ox, oy, oz, dx, dy, dz, b, maxd)
            if h and (best is None or h[0] < best[0]):
                best = (h[0], name)
        if best is None:
            return None
        self.last_part = best[1]
        return best[0]


