def hanging_box(kind, x, y, z, face, motif=0):
    """The thin box a painting / item frame takes up on its wall."""
    fx, fz = FACING_DIR[face & 3]
    if kind == 'painting':
        _n, pw, ph, _u, _v = PAINTINGS[motif % len(PAINTINGS)]
        half, y0, y1 = pw / 2.0, y, y + ph
    else:
        half, y0, y1 = 0.375, y + 0.125, y + 0.875
    t = 1 / 16.
    if fx:
        return (x - t, y0, z - half, x + t, y1, z + half)
    return (x - half, y0, z - t, x + half, y1, z + t)


def hanging_ray(e, ox, oy, oz, dx, dy, dz, maxd):
    b = hanging_box(e.kind, e.x, e.y, e.z, e.__dict__.get('face', 0), e.__dict__.get('motif', 0))
    h = ray_box(ox, oy, oz, dx, dy, dz, b, maxd)
    return h[0] if h else None


