class ProxyEntity(Entity):
    """A LAN client's view of an entity simulated by the host."""

    def __init__(self, eid, kind, x, y, z):
        Entity.__init__(self, x, y, z)
        self.id = eid
        self.kind = kind
        self.tx, self.ty, self.tz = x, y, z
        self.tyaw = 0.0
        self.tpitch = 0.0
        self.item = 0
        self.count = 1
        self.dmg = 0
        self.fuse = 0.0
        self.spin = 0.0
        self.sheared = False
        self.angry = False
        self.rider = None
        self.size = 1
        self.attacking = False
        self.flaming = False
        self.held_item = 0
        self.name = {'leo': 'Leo', 'charlie': 'Charlie Pedge'}.get(kind, '')
        self.value = 1
        self.profession = 0
        self.color = 0
        self.carried = 0
        self.beam = None
        self.dying = 0.0
        self.block = B_SAND
        self.hp = 100
        cls = MOB_CLASSES.get(kind) or {'item': ItemEntity, 'arrow': Arrow, 'boat': Boat, 'tnt': TNT,
                                        'fireball': Fireball, 'smallfire': SmallFireball, 'falling': FallingBlock,
                                        'snowball': Thrown, 'egg': Thrown, 'xp': XPOrb, 'pearl': Thrown,
                                        'eye': EyeEntity, 'crystal': EnderCrystal, 'dragon': EnderDragon,
                                        'minecart': Minecart, 'bobber': Bobber, 'splash': Thrown,
                                        'painting': Painting, 'frame': ItemFrame, 'wskull': WitherSkull}.get(kind)
        if cls:
            self.hw, self.h = cls.hw, cls.h
        if kind == 'pigman':
            self.held_item = tool_id('sword', 3)
        elif kind == 'witherskel':
            self.held_item = tool_id('sword', 1)

def _term(k, var='', first=False):
    """k * var written nicely: 'x', '- 3x', '+ 12'."""
    if k == 0:
        return ''
    mag = abs(k)
    body = (var if mag == 1 and var else '%d%s' % (mag, var))
    if first:
        return ('-' if k < 0 else '') + body
    return ('- ' if k < 0 else '+ ') + body


def _poly(*terms):
    return ' '.join(t for t in terms if t) or '0'


def math_problem(rng, kind=None):
    """A hard-ish maths problem with a whole-number answer -> (text, answer, method hint)."""
    kind = rng.randrange(11) if kind is None else kind
    if kind == 0:
        while True:
            a, c = rng.randint(3, 19), rng.randint(2, 15)
            if a != c:
                break
        x = rng.choice([v for v in range(-25, 61) if v not in (0, 1)])
        b = rng.choice([v for v in range(-99, 100) if v])
        d = (a - c) * x + b
        ans = x
        text = 'solve for x: %s = %s' % (_poly(_term(a, 'x', True), _term(b)), _poly(_term(c, 'x', True), _term(d)))
        hint = 'take %dx from both sides, then get x on its own' % c
    elif kind == 1:
        a, b = rng.randint(120, 999), rng.randint(13, 89)
        d = rng.randint(11, 29)
        c = d * rng.randint(20, 180)
        ans = a * b - c // d
        text = 'what is %d * %d - %d / %d ?' % (a, b, c, d)
        hint = 'do the * and the / first (%d / %d = %d), then subtract' % (c, d, c // d)
    elif kind == 2:
        a, b, c = rng.randint(13, 45), rng.randint(5, 17), rng.randint(9, 31)
        ans = a * a + b ** 3 - c * c
        text = 'what is %d^2 + %d^3 - %d^2 ?' % (a, b, c)
        hint = '^2 means times itself (%d * %d), ^3 means three of them (%d * %d * %d)' % (a, a, b, b, b)
    elif kind == 3:
        r1, r2 = rng.randint(4, 29), -rng.randint(3, 24)
        p, q = -(r1 + r2), r1 * r2
        ans = r1
        text = 'what is the positive solution of %s = 0 ?' % _poly('x^2', _term(p, 'x'), _term(q))
        hint = 'find two numbers that multiply to %d and add up to %d' % (q, p)
    elif kind == 4:
        n = rng.randint(60, 480)
        ans = n * (n + 1) // 2
        text = 'what is 1 + 2 + 3 + ... + %d ?' % n
        hint = 'pair them up: 1 + %d, 2 + %d, ... every pair makes %d. how many pairs?' % (n, n - 1, n + 1)
    elif kind == 5:
        base = rng.randint(21, 480) * 20
        pct = rng.choice((5, 15, 35, 45, 55, 65, 85, 95))
        ans = base * pct // 100
        text = 'what is %d%% of %d ?' % (pct, base)
        hint = '1%% of %d is %s, so times that by %d' % (base, ('%g' % (base / 100.0)), pct)
    elif kind == 6:
        a, b, m = rng.randint(3, 9), rng.randint(11, 25), rng.choice((7, 11, 13, 17, 19, 23))
        ans = pow(a, b, m)
        text = 'what is the remainder when %d^%d is divided by %d ?' % (a, b, m)
        hint = 'keep multiplying by %d, but only keep the remainder after dividing by %d each time' % (a, m)
    elif kind == 7:
        x, y = rng.randint(7, 48), rng.randint(3, 40)
        ans = x * y
        text = 'if x + y = %d and x - y = %d, what is x * y ?' % (x + y, x - y)
        hint = 'add the two equations: 2x = %d' % (2 * x)
    elif kind == 8:
        a, b, c, x = rng.randint(2, 6), rng.randint(2, 9), rng.randint(2, 12), rng.randint(2, 6)
        ans = 3 * a * x * x - 2 * b * x + c
        text = "f(x) = %dx^3 - %dx^2 + %dx - 7. what is f'(%d) ?" % (a, b, c, x)
        hint = "f'(x) = %dx^2 - %dx + %d (bring each power down, lower it by one), then put in x = %d" % (
            3 * a, 2 * b, c, x)
    elif kind == 9:
        n, k = rng.randint(10, 20), rng.randint(3, 5)
        ans = math.comb(n, k) if hasattr(math, 'comb') else math.factorial(n) // (math.factorial(k) * math.factorial(n - k))
        text = 'how many ways can you choose %d things from %d ?' % (k, n)
        hint = '(%s) / (%s)' % (' * '.join(str(n - i) for i in range(k)), ' * '.join(str(k - i) for i in range(k)))
    else:
        a, b = rng.randint(12, 96), rng.randint(12, 96)
        ans = a * b // math.gcd(a, b)
        text = 'what is the lowest common multiple of %d and %d ?' % (a, b)
        hint = 'the smallest number both %d and %d divide into exactly (%d * %d / %d)' % (a, b, a, b, math.gcd(a, b))
    return text, ans, hint

# ----------------------------------------------------------------------------
#  SAVING  (one file per world in a folder next to this script)
# ----------------------------------------------------------------------------
def script_dir():
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except NameError:
        return os.getcwd()


SAVE_DIR = os.path.join(script_dir(), 'blockcraft_worlds')
OPTIONS_FILE = os.path.join(SAVE_DIR, 'options.json')


def safe_name(name):
    s = ''.join(c for c in name if c.isalnum() or c in ' -_').strip()
    return s[:32] or 'World'


def list_worlds():
    out = []
    try:
        names = os.listdir(SAVE_DIR)
    except OSError:
        return out
    for fn in names:
        if not fn.endswith('.bcw'):
            continue
        p = os.path.join(SAVE_DIR, fn)
        try:
            with open(p, 'rb') as f:
                head = f.readline(8192)
            meta = json.loads(head.decode('utf-8'))
            meta['file'] = p
            meta['mtime'] = os.path.getmtime(p)
            out.append(meta)
        except Exception:
            continue
    out.sort(key=lambda m: -m['mtime'])
    return out


def write_file_atomic(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + '.tmp'
    with open(tmp, 'wb') as f:
        f.write(data)
    for attempt in range(8):
        try:
            os.replace(tmp, path)
            return
        except PermissionError:
            if attempt == 7:
                raise
            time.sleep(0.05)


def stack_json(s):
    return list(s) if s else None


def stack_load(s):
    return [int(s[0]), int(s[1]), int(s[2])] if s else None


# ----------------------------------------------------------------------------
#  COSMETIC LIBRARY: your saved skins and capes (blockcraft_worlds/skins, /capes) and the pictures LAN
#  players sent (skins/cache).  Every picture is kept as our own PNG of the cleaned-up raster, named by
#  its hash, so the same picture always has the same file and the same id everywhere.
# ----------------------------------------------------------------------------
SKIN_DIR = os.path.join(SAVE_DIR, 'skins')
CAPE_DIR = os.path.join(SAVE_DIR, 'capes')
COS_CACHE_DIR = os.path.join(SKIN_DIR, 'cache')
COS_LIBRARY_FILE = os.path.join(SKIN_DIR, 'library.json')


class CosmeticLibrary:
    MAX_SKINS = 64
    MAX_CAPES = 32
    MAX_CACHE = 160                       # pictures from other players kept on disk
    NAME_LEN = 24

    def __init__(self):
        self.skins = []                   # [{'id', 'name', 'model', 'layers', 'created'}], newest last
        self.capes = []                   # [{'id', 'name', 'created'}]
        self.rasters = {}                 # ('skin' | 'cape', id) -> bytearray RGBA (decoded on demand)
        self.loaded = False

    # -- the index ---------------------------------------------------------------------------------
    def load(self):
        self.loaded = True
        try:
            with open(COS_LIBRARY_FILE, 'r', encoding='utf-8') as f:
                d = json.load(f)
        except Exception:
            d = {}
        self.skins, self.capes = [], []
        for e in (d.get('skins') or []) if isinstance(d, dict) else []:
            if not isinstance(e, dict) or not is_cosmetic_hash(e.get('id')):
                continue
            if not os.path.exists(self.path('skin', e['id'])):
                continue
            self.skins.append({'id': e['id'], 'name': self.clean_name(e.get('name'), 'Skin'),
                               'model': e.get('model') if e.get('model') in SKIN_MODELS else 'classic',
                               'layers': int(e.get('layers', LAYER_ALL)) & LAYER_ALL,
                               'created': float(e.get('created') or 0.0)})
        for e in (d.get('capes') or []) if isinstance(d, dict) else []:
            if not isinstance(e, dict) or not is_cosmetic_hash(e.get('id')):
                continue
            if not os.path.exists(self.path('cape', e['id'])):
                continue
            self.capes.append({'id': e['id'], 'name': self.clean_name(e.get('name'), 'Cape'),
                               'created': float(e.get('created') or 0.0)})

    def save(self):
        try:
            write_file_atomic(COS_LIBRARY_FILE, json.dumps({'skins': self.skins, 'capes': self.capes}).encode('utf-8'))
        except Exception:
            traceback.print_exc()

    def clean_name(self, name, default):
        s = ''.join(c for c in str(name or '') if c.isprintable() and c not in '\\/:*?"<>|').strip()
        return s[:self.NAME_LEN] or default

    def unique_name(self, kind, base):
        base = self.clean_name(base, 'Skin' if kind == 'skin' else 'Cape')
        names = {e['name'].lower() for e in (self.skins if kind == 'skin' else self.capes)}
        if base.lower() not in names:
            return base
        k = 2
        while ('%s %d' % (base, k)).lower() in names:
            k += 1
        return ('%s %d' % (base, k))[:self.NAME_LEN]

    def entries(self, kind):
        return self.skins if kind == 'skin' else self.capes

    def find(self, kind, h):
        for e in self.entries(kind):
            if e['id'] == h:
                return e
        return None

    # -- files -------------------------------------------------------------------------------------
    def path(self, kind, h, cache=False):
        if cache:
            return os.path.join(COS_CACHE_DIR, h + '.png')
        return os.path.join(SKIN_DIR if kind == 'skin' else CAPE_DIR, h + '.png')

    def size(self, kind):
        return (SKIN_W, SKIN_H) if kind == 'skin' else (CAPE_W, CAPE_H)

    def raster(self, kind, h):
        """The RGBA pixels of a saved or cached picture (None when we don't have it).  Decoded once."""
        if not is_cosmetic_hash(h):
            return None
        key = (kind, h)
        r = self.rasters.get(key)
        if r is not None:
            return r
        for path in (self.path(kind, h), self.path(kind, h, cache=True)):
            try:
                with open(path, 'rb') as f:
                    data = f.read()
            except OSError:
                continue
            try:
                w, hh, rgba = png_decode(data, allowed=(self.size(kind),))
            except SkinError:
                continue
            if cosmetic_hash(rgba) != h:                  # a tampered or stale file: not that picture
                continue
            self.rasters[key] = rgba
            return rgba
        return None

    def png(self, kind, h):
        """PNG bytes of a picture we have, re-encoded from its pixels (what goes over the LAN)."""
        r = self.raster(kind, h)
        if r is None:
            return None
        w, hh = self.size(kind)
        return png_encode(r, w, hh)

    def write(self, kind, h, rgba, cache=False):
        w, hh = self.size(kind)
        write_file_atomic(self.path(kind, h, cache), png_encode(rgba, w, hh))
        self.rasters[(kind, h)] = bytearray(rgba)

    # -- your skins and capes ----------------------------------------------------------------------
    def add_skin(self, rgba, name, model='classic', layers=LAYER_ALL):
        """Save a (normalized 64x64) skin.  The same picture saved twice is one entry (renamed)."""
        h = cosmetic_hash(rgba)
        e = self.find('skin', h)
        if e is None:
            if len(self.skins) >= self.MAX_SKINS:
                raise SkinError('The skin library is full (%d skins) - delete one first' % self.MAX_SKINS)
            e = {'id': h, 'name': self.unique_name('skin', name), 'model': model if model in SKIN_MODELS else 'classic',
                 'layers': int(layers) & LAYER_ALL, 'created': time.time()}
            self.skins.append(e)
        self.write('skin', h, rgba)
        self.save()
        return e

    def add_cape(self, rgba, name):
        h = cosmetic_hash(rgba)
        e = self.find('cape', h)
        if e is None:
            if len(self.capes) >= self.MAX_CAPES:
                raise SkinError('The cape library is full (%d capes) - delete one first' % self.MAX_CAPES)
            e = {'id': h, 'name': self.unique_name('cape', name), 'created': time.time()}
            self.capes.append(e)
        self.write('cape', h, rgba)
        self.save()
        return e

    def rename(self, kind, h, name):
        e = self.find(kind, h)
        if e:
            e['name'] = self.unique_name(kind, name) if self.clean_name(name, '').lower() != e['name'].lower() else e['name']
            self.save()
        return e

    def set_skin_options(self, h, model=None, layers=None):
        e = self.find('skin', h)
        if e:
            if model in SKIN_MODELS:
                e['model'] = model
            if layers is not None:
                e['layers'] = int(layers) & LAYER_ALL
            self.save()
        return e

    def delete(self, kind, h):
        e = self.find(kind, h)
        if e is None:
            return False
        self.entries(kind).remove(e)
        self.rasters.pop((kind, h), None)
        try:
            os.remove(self.path(kind, h))
        except OSError:
            pass
        self.save()
        return True

    # -- other players' pictures -------------------------------------------------------------------
    def cache_put(self, kind, h, rgba):
        """Keep a picture a LAN player sent (it was decoded and checked already), so a reconnect is instant."""
        if self.find(kind, h) is not None:
            return
        try:
            self.write(kind, h, rgba, cache=True)
        except OSError:
            traceback.print_exc()
        self.trim_cache()

    def trim_cache(self):
        try:
            names = [n for n in os.listdir(COS_CACHE_DIR) if n.endswith('.png')]
        except OSError:
            return
        if len(names) <= self.MAX_CACHE:
            return
        paths = [os.path.join(COS_CACHE_DIR, n) for n in names]
        paths.sort(key=lambda p: os.path.getmtime(p) if os.path.exists(p) else 0)
        for p in paths[:len(paths) - self.MAX_CACHE]:
            try:
                os.remove(p)
            except OSError:
                pass

    def has(self, kind, h):
        return self.raster(kind, h) is not None


# ----------------------------------------------------------------------------
#  SKIN EDITOR: the pixels of a skin being drawn on, and the tools (no OpenGL in here; the screen is in
#  the game).  Every stroke is one undo step.
# ----------------------------------------------------------------------------
class SkinEditor:
    MAX_UNDO = 64
    TOOLS = (('pencil', 'Pencil (P)', 'pencil'), ('eraser', 'Eraser (E)', 'eraser'), ('dropper', 'Eyedropper (I)', 'dropper'),
             ('bucket', 'Paint bucket (B)', 'bucket'))
    PARTS = (('head', 'Head'), ('body', 'Body'), ('arm_r', 'R.Arm'), ('arm_l', 'L.Arm'), ('leg_r', 'R.Leg'), ('leg_l', 'L.Leg'))
    PART_TAGS = {'head': 'head', 'body': 'body', 'arm_r': 'armR', 'arm_l': 'armL', 'leg_r': 'legB', 'leg_l': 'legA'}

    def __init__(self, rgba, model='classic', source=('new', None), name='Skin'):
        self.rgba = bytearray(rgba)
        self.model = model if model in SKIN_MODELS else 'classic'
        self.source = source
        self.name = name
        self.tool = 'pencil'
        self.last_tool = 'pencil'
        self.color = (255, 255, 255, 255)
        self.hsv = [0.0, 0.0, 1.0]
        self.recent = [(60, 60, 150, 255), (0, 170, 170, 255), (225, 175, 140, 255), (70, 45, 25, 255), (255, 255, 255, 255),
                       (20, 20, 20, 255)]
        self.mirror = False
        self.visible = {p: [True, True] for p, _ in self.PARTS}
        self.undo_stack, self.redo_stack = [], []
        self.dirty = False
        self.changed = True
        self.clipboard = None                    # (face name, w, h, bytes)
        self.stroke = None                       # the last texel of the stroke being drawn, or None
        self.hover = None

    # -- pixels --------------------------------------------------------------------------------
    def inside(self, x, y):
        return 0 <= x < SKIN_W and 0 <= y < SKIN_H

    def get(self, x, y):
        if not self.inside(x, y):
            return None
        i = (y * SKIN_W + x) * 4
        return tuple(self.rgba[i:i + 4])

    def _put(self, x, y, c):
        if self.inside(x, y) and skin_part_at(x, y, self.model) is not None:
            i = (y * SKIN_W + x) * 4
            if tuple(self.rgba[i:i + 4]) != tuple(c):
                self.rgba[i:i + 4] = bytes(c)
                self.changed = self.dirty = True

    def paint(self, x, y, c=None):
        """Draw one texel (and its mirror twin when mirroring); c None = erase (transparent)."""
        c = (0, 0, 0, 0) if c is None else c
        self._put(x, y, c)
        if self.mirror:
            m = skin_mirror_texel(x, y, self.model)
            if m:
                self._put(m[0], m[1], c)

    def paint_line(self, x0, y0, x1, y1, c=None):
        n = max(abs(x1 - x0), abs(y1 - y0))
        for i in range(n + 1):
            f = i / float(n) if n else 0.0
            self.paint(int(round(x0 + (x1 - x0) * f)), int(round(y0 + (y1 - y0) * f)), c)

    def pick(self, x, y):
        c = self.get(x, y)
        return c if c and c[3] else None

    def fill(self, x, y, c):
        """Flood fill the face under x, y with c (texels of the same colour, touching)."""
        where = skin_part_at(x, y, self.model)
        if where is None:
            return
        target = self.get(x, y)
        if target == tuple(c):
            return
        todo = [(x, y)]
        seen = set()
        while todo:
            px, py = todo.pop()
            if (px, py) in seen or not self.inside(px, py):
                continue
            seen.add((px, py))
            if skin_part_at(px, py, self.model) != where or self.get(px, py) != target:
                continue
            self.paint(px, py, c)
            todo.extend(((px + 1, py), (px - 1, py), (px, py + 1), (px, py - 1)))

    def face_rect(self, x, y):
        """(x0, y0, w, h, face name) of the face under a texel, or None."""
        boxes = SKIN_BOXES_SLIM if self.model == 'slim' else SKIN_BOXES
        for part, layers in boxes.items():
            for layer, (u, v, bw, bh, bd) in enumerate(layers):
                f = _skin_face_at(x - u, y - v, bw, bh, bd)
                if f:
                    name, ox, oy, fw, fh, lx, ly = f
                    return u + ox, v + oy, fw, fh, name
        return None

    def clear_face(self, x, y):
        r = self.face_rect(x, y)
        if not r:
            return False
        self.push_undo()
        x0, y0, fw, fh, _ = r
        for yy in range(y0, y0 + fh):
            for xx in range(x0, x0 + fw):
                self.paint(xx, yy, None)
        return True

    def clear_part(self, part, layer):
        boxes = SKIN_BOXES_SLIM if self.model == 'slim' else SKIN_BOXES
        u, v, bw, bh, bd = boxes[part][layer]
        self.push_undo()
        for yy in range(v, v + bd + bh):
            for xx in range(u, u + 2 * bd + 2 * bw):
                at = skin_part_at(xx, yy, self.model)
                if at and at[0] == part and at[1] == layer:
                    self._put(xx, yy, (0, 0, 0, 0))

    def copy_face(self, x, y):
        r = self.face_rect(x, y)
        if not r:
            return False
        x0, y0, fw, fh, name = r
        buf = bytearray()
        for yy in range(y0, y0 + fh):
            buf += self.rgba[((yy * SKIN_W) + x0) * 4:((yy * SKIN_W) + x0 + fw) * 4]
        self.clipboard = (name, fw, fh, bytes(buf))
        return True

    def paste_face(self, x, y):
        r = self.face_rect(x, y)
        if not r or not self.clipboard:
            return False
        x0, y0, fw, fh, _ = r
        name, cw, ch, buf = self.clipboard
        self.push_undo()
        for yy in range(min(fh, ch)):
            for xx in range(min(fw, cw)):
                i = (yy * cw + xx) * 4
                self._put(x0 + xx, y0 + yy, tuple(buf[i:i + 4]))
        return True

    # -- undo ----------------------------------------------------------------------------------
    def push_undo(self):
        self.undo_stack.append(bytes(self.rgba))
        if len(self.undo_stack) > self.MAX_UNDO:
            del self.undo_stack[0]
        self.redo_stack = []

    def begin_stroke(self, x, y):
        if self.stroke is None:
            self.push_undo()
        self.stroke = (x, y)

    def end_stroke(self):
        if self.stroke is not None and self.undo_stack and self.undo_stack[-1] == bytes(self.rgba):
            self.undo_stack.pop()                 # (a stroke that changed nothing is not an undo step)
        self.stroke = None

    def undo(self):
        if not self.undo_stack:
            return False
        self.redo_stack.append(bytes(self.rgba))
        self.rgba = bytearray(self.undo_stack.pop())
        self.changed = self.dirty = True
        return True

    def redo(self):
        if not self.redo_stack:
            return False
        self.undo_stack.append(bytes(self.rgba))
        self.rgba = bytearray(self.redo_stack.pop())
        self.changed = self.dirty = True
        return True

    # -- colours -------------------------------------------------------------------------------
    def set_color(self, c):
        c = (int(c[0]), int(c[1]), int(c[2]), 255)
        self.color = c
        h, s, v = colorsys.rgb_to_hsv(c[0] / 255.0, c[1] / 255.0, c[2] / 255.0)
        if s > 0.001 and v > 0.001:
            self.hsv[0] = h
        self.hsv[1], self.hsv[2] = s, v

    def set_hsv(self, h=None, s=None, v=None):
        if h is not None:
            self.hsv[0] = clamp(h, 0.0, 1.0)
        if s is not None:
            self.hsv[1] = clamp(s, 0.0, 1.0)
        if v is not None:
            self.hsv[2] = clamp(v, 0.0, 1.0)
        r, g, b = colorsys.hsv_to_rgb(self.hsv[0] % 1.0, self.hsv[1], self.hsv[2])
        self.color = (int(round(r * 255)), int(round(g * 255)), int(round(b * 255)), 255)

    def remember_color(self):
        c = self.color
        if c in self.recent:
            self.recent.remove(c)
        self.recent.insert(0, c)
        del self.recent[12:]

    def hex(self):
        return '%02x%02x%02x' % self.color[:3]

    def set_hex(self, text):
        t = text.strip().lstrip('#')
        if len(t) == 3:
            t = ''.join(ch * 2 for ch in t)
        if len(t) != 6:
            return False
        try:
            v = int(t, 16)
        except ValueError:
            return False
        self.set_color(((v >> 16) & 255, (v >> 8) & 255, v & 255))
        return True

    # -- what the preview shows ----------------------------------------------------------------
    def layer_mask(self):
        m = 0
        for part, bit in (('head', LAYER_HAT), ('body', LAYER_JACKET), ('arm_r', LAYER_SLEEVE_R), ('arm_l', LAYER_SLEEVE_L),
                          ('leg_r', LAYER_PANTS_R), ('leg_l', LAYER_PANTS_L)):
            if self.visible[part][1]:
                m |= bit
        return m

    def hidden(self):
        return set((self.PART_TAGS[p], 0) for p in self.visible if not self.visible[p][0])

    def cos(self):
        return {'skin': ('edit', self.model, self.layer_mask()), 'cape': None, 'hide': self.hidden()}


# ----------------------------------------------------------------------------
#  CAPE PHYSICS: how a cape hangs and swings.  A spring-damped angle away from the back (lifted by running,
#  falling, water) and a sideways sway (turning, strafing), worked out from how the player moves between
#  frames - so LAN players' capes move exactly like yours, from their positions alone.
# ----------------------------------------------------------------------------
class CapeState:
    SEGMENTS = 6

    def __init__(self, phase=0.0):
        self.pitch = 6.0                  # degrees the top of the cape hangs away from the back
        self.pvel = 0.0
        self.roll = 0.0                   # sideways swing (degrees)
        self.rvel = 0.0
        self.speed = 0.0                  # smoothed forward speed (blocks / s)
        self.last = None                  # (x, y, z, yaw) last frame
        self.phase = phase
        self.t = 0.0

    def update(self, dt, x, y, z, yaw, on_ground=True, sprint=False, sneak=False, in_water=False):
        dt = clamp(dt, 0.001, 0.1)
        self.t += dt
        if self.last is None:
            self.last = (x, y, z, yaw)
            return
        lx, ly, lz, lyaw = self.last
        self.last = (x, y, z, yaw)
        dx, dy, dz = x - lx, y - ly, z - lz
        if abs(dx) > 8 or abs(dz) > 8 or abs(dy) > 8:          # teleported: no swing from that
            dx = dy = dz = 0.0
        yr = math.radians(yaw)
        fx, fz = math.sin(yr), -math.cos(yr)                  # where the player faces
        fwd = (dx * fx + dz * fz) / dt
        side = (dx * fz - dz * fx) / dt
        vy = dy / dt
        dyaw = (yaw - lyaw + 180.0) % 360.0 - 180.0
        yaw_rate = clamp(dyaw / dt, -720.0, 720.0)
        self.speed += (fwd - self.speed) * min(1.0, dt * 10.0)
        # the angle the cape wants
        target = 6.0 + clamp(self.speed, -2.0, 9.0) * 8.5
        if sprint and self.speed > 3.0:
            target += 6.0
        if not on_ground:
            if vy < -2.0:
                target += min(45.0, (-vy - 2.0) * 5.0)        # falling: the air lifts it
            elif vy > 1.0:
                target -= min(10.0, vy * 2.0)                  # rising: it trails down
        if in_water:
            target = target * 0.5 + 18.0
        if sneak:
            target += 10.0
        idle = math.sin(self.t * 2.1 + self.phase) * 1.6 + math.sin(self.t * 3.7 + self.phase * 2) * 0.7
        target = clamp(target + idle, -8.0, 78.0)
        k, damp = 90.0, 8.5
        if abs(self.speed) < 0.3 and on_ground:
            k, damp = 60.0, 6.5                                # settling: a slower, softer swing
        self.pvel += ((target - self.pitch) * k - self.pvel * damp) * dt
        self.pitch += self.pvel * dt
        self.pitch = clamp(self.pitch, -14.0, 85.0)
        rt = clamp(-yaw_rate * 0.07 - side * 5.0, -40.0, 40.0)
        self.rvel += ((rt - self.roll) * 70.0 - self.rvel * 7.5) * dt
        self.roll += self.rvel * dt
        self.roll = clamp(self.roll, -55.0, 55.0)

    def angles(self):
        """The angle of each segment from the vertical (the top one first): a cape bends more the lower down."""
        n = self.SEGMENTS
        p = self.pitch
        return [clamp(p * (1.0 + 0.22 * i) + (1.5 if p > 10 else 0.0) * i, -20.0, 88.0) for i in range(n)]


# ----------------------------------------------------------------------------
#  PLAYER ANIMATION: a state machine with blending.  Every player model (you in third person, LAN players,
#  the menus' previews) owns an AnimState that turns what the player is doing - standing, walking, sprinting,
#  the phases of a jump, falling, landing, swimming, climbing, sneaking, sitting - into a pose, eases between
#  poses instead of snapping, and lays the attack swing (per weapon, four-hit combos), hit reactions and the
#  blocking pose over the top.  Five styles scale it all.  No OpenGL in here.
# ----------------------------------------------------------------------------
ANIM_STYLES = [('classic', 'Classic', 'The old game: no idle motion, snappy swings'),
               ('smooth', 'Smooth', 'Soft blends, gentle breathing, easy landings'),
               ('pvp', 'PvP', 'Responsive: lean into sprints, sharp combos, hit reactions'),
               ('stylized', 'Stylized', 'Big, expressive motion on every move'),
               ('minimal', 'Minimal', 'Quiet: just enough to read what a player does')]
ANIM_STYLE_IDS = [s[0] for s in ANIM_STYLES]
ANIM_PARAMS = {
    'classic': dict(idle=0.0, walk=1.0, arms=1.0, lean=0.0, head=1.0, blend=0.06, land=0.25, hit=0.45, jump=0.3,
                    attack=1.0, swing_t=1.0, shake=0.6),
    'smooth': dict(idle=0.6, walk=1.0, arms=0.9, lean=0.5, head=1.0, blend=0.16, land=0.7, hit=0.8, jump=0.8,
                   attack=0.9, swing_t=1.1, shake=0.7),
    'pvp': dict(idle=0.5, walk=1.05, arms=1.1, lean=0.9, head=1.0, blend=0.09, land=1.0, hit=1.0, jump=1.0,
                attack=1.1, swing_t=0.9, shake=1.0),
    'stylized': dict(idle=1.0, walk=1.25, arms=1.4, lean=1.2, head=1.2, blend=0.12, land=1.3, hit=1.3, jump=1.3,
                     attack=1.25, swing_t=1.0, shake=1.2),
    'minimal': dict(idle=0.15, walk=0.8, arms=0.6, lean=0.25, head=0.6, blend=0.12, land=0.4, hit=0.4, jump=0.4,
                    attack=0.8, swing_t=1.0, shake=0.4),
}
# weapon classes (what the swing looks like): index -> name; packed into the swing kind
WEAPON_CLASSES = ('fist', 'sword', 'axe', 'mace', 'tool', 'item', 'shield', 'bow')
SWING_SECS = {'fist': 0.3, 'sword': 0.34, 'axe': 0.52, 'mace': 0.68, 'tool': 0.4, 'item': 0.4, 'shield': 0.36, 'bow': 0.4}
ATTACK_COOLDOWN = {'fist': 0.3, 'sword': 0.3, 'axe': 0.5, 'mace': 0.7, 'tool': 0.35, 'item': 0.3, 'shield': 0.35, 'bow': 0.3}


def weapon_class(item):
    """0 fist .. 7 bow: the class of what is in the hand, for the swing animation."""
    if not item or item < 256 or item not in ITEMS:
        return 0 if not item or item < 256 else 5
    t = ITEMS[item].get('tool')
    if t == 'sword':
        return 1
    if t == 'axe':
        return 2
    if t == 'mace':
        return 3
    if t in ('pick', 'shovel', 'hoe'):
        return 4
    if t == 'shield':
        return 6
    if item == I_BOW:
        return 7
    return 5


def swing_kind_pack(wclass, combo, crit, sprint):
    return (int(wclass) & 7) | ((int(combo) & 3) << 3) | ((1 if crit else 0) << 5) | ((1 if sprint else 0) << 6)


def swing_kind_unpack(k):
    k = int(k or 0)
    return k & 7, (k >> 3) & 3, bool(k & 32), bool(k & 64)


def anim_pack(style, on_ground, sprint, vy, in_water, on_ladder, flying, hit_dir, swing_kind):
    """Everything about a player's animation that the state packet carries, as one int."""
    st = ANIM_STYLE_IDS.index(style) if style in ANIM_STYLE_IDS else 2
    vys = 0 if abs(vy) < 1.0 else (1 if vy > 0 else (2 if vy > -8.0 else 3))
    hd = 15 if hit_dir is None else int(((hit_dir % 360.0) / 24.0) + 0.5) % 15
    return (st | ((1 if on_ground else 0) << 3) | ((1 if sprint else 0) << 4) | (vys << 5) | ((1 if in_water else 0) << 7)
            | ((1 if on_ladder else 0) << 8) | ((1 if flying else 0) << 9) | (hd << 10) | ((int(swing_kind) & 127) << 14))


def anim_unpack(v):
    v = int(v)
    vys = (v >> 5) & 3
    hd = (v >> 10) & 15
    return dict(style=ANIM_STYLE_IDS[v & 7] if (v & 7) < len(ANIM_STYLE_IDS) else 'pvp', on_ground=bool(v & 8),
                sprint=bool(v & 16), vy=(0.0, 4.0, -4.0, -12.0)[vys], in_water=bool(v & 128), on_ladder=bool(v & 256),
                flying=bool(v & 512), hit_dir=None if hd == 15 else hd * 24.0, swing_kind=(v >> 14) & 127)


def _ease_out(u):
    u = clamp(u, 0.0, 1.0)
    return 1 - (1 - u) ** 3


def _smooth(u):
    u = clamp(u, 0.0, 1.0)
    return u * u * (3 - 2 * u)


def swing_envelope(f, wclass):
    """(strike 0..1 with a little follow-through, wind-up 0..1) over a swing's progress f: a fast weapon gets
    there at once, an axe winds up, a mace heaves."""
    if wclass == 2:                                           # axe: a wind-up, a heavy chop, held, then back
        a, b, c = 0.2, 0.45, 0.75
    elif wclass == 3:                                         # mace: a long heave over the shoulder
        a, b, c = 0.28, 0.5, 0.78
    else:
        a, b, c = 0.08, 0.38, 0.64
    if f < a:
        return 0.0, f / a
    if f < b:
        u = (f - a) / (b - a)
        return _ease_out(u) if wclass not in (2, 3) else _smooth(u), 1 - u
    if f < c:
        u = (f - b) / (c - b)
        return 1.0 + 0.12 * math.sin(u * math.pi), 0.0
    u = (f - c) / max(1e-6, 1 - c)
    return 1 - _smooth(u), 0.0


class AnimState:
    CHANNELS = ('head', 'body', 'armR', 'armL', 'legA', 'legB')
    STATES = ('idle', 'walk', 'sprint', 'sneak', 'jump', 'rise', 'apex', 'fall', 'land', 'swim', 'climb', 'sit', 'fly')

    def __init__(self, seed=0.0):
        self.cur = {c: [0.0, 0.0, 0.0] for c in self.CHANNELS}
        self.cur_y = 0.0
        self.cur_torso = [0.0, 0.0, 0.0]
        self.pose = self.make_pose()
        self.state = 'idle'
        self.state_t = 0.0
        self.tau = 0.1
        self.t = seed
        self.air_t = 0.0
        self.land_t = 9.0
        self.land_amt = 0.0
        self.was_ground = True
        self.last_pos = None
        self.est_vy = 0.0
        self.min_vy = 0.0
        self.speed = 0.0
        self.swim_t = 0.0
        self.hit_seq = 0
        self.hit_t = 0.0
        self.hit_dir = None
        self.frame = -1
        self.frame_t = -1.0

    def make_pose(self):
        p = {c: tuple(self.cur[c]) for c in self.CHANNELS}
        p['y'] = self.cur_y
        p['torso'] = tuple(self.cur_torso)
        return p

    # -- which state ---------------------------------------------------------------------------
    def pick_state(self, inp, vy, speed):
        if inp.get('sitting'):
            return 'sit'
        if inp.get('flying') and not inp['on_ground']:
            return 'fly'
        if inp.get('in_water') and not inp['on_ground']:
            return 'swim'
        if inp.get('on_ladder') and not inp['on_ground']:
            return 'climb'
        if not inp['on_ground']:
            if self.air_t < 0.1 and vy > 0.5:
                return 'jump'
            if vy > 1.2:
                return 'rise'
            if vy < -1.6:
                return 'fall'
            return 'apex'
        if self.land_t < 0.28:
            return 'land'
        if inp.get('sneak'):
            return 'sneak'
        if speed > 0.25:
            return 'sprint' if (inp.get('sprint') or speed > 5.0) else 'walk'
        return 'idle'

    def transition_tau(self, old, new, st):
        base = st['blend']
        if base <= 0.065:
            return base
        if new == 'land':
            return 0.07
        if new == 'jump':
            return 0.05
        if old == 'land':
            return base * 1.8
        if new == 'swim' or old == 'swim':
            return base * 2.0
        if (old, new) in (('walk', 'sprint'), ('sprint', 'walk')):
            return base * 1.3
        if new in ('fall', 'apex', 'rise'):
            return base * 1.5
        return base

    # -- the pose for a state ------------------------------------------------------------------
    def locomotion(self, inp, st, vy, speed):
        """The target pose of the current state: tag -> [rx, ry, rz], plus y and torso offsets."""
        t = self.t
        walk, limb = inp.get('walk', 0.0), inp.get('limb', 0.0)
        idle, lean, arms = st['idle'], st['lean'], st['arms']
        P = {c: [0.0, 0.0, 0.0] for c in self.CHANNELS}
        y = 0.0
        torso = [0.0, 0.0, 0.0]
        s = self.state
        sw = math.sin(walk * 2.2) * 40 * min(1.0, limb * 1.3)
        cw = math.cos(walk * 2.2)
        if s in ('idle', 'walk', 'sprint', 'sneak', 'land'):
            # breathing, a little sway, the arms not quite rigid (scaled by the style's idle amount)
            br = math.sin(t * 1.6)
            P['body'][0] += 0.8 * br * idle
            torso[1] += 0.006 * br * idle
            P['armR'][2] += -(1.5 + 0.9 * math.sin(t * 1.6 + 0.4)) * idle
            P['armL'][2] += (1.5 + 0.9 * math.sin(t * 1.6 + 0.4)) * idle
            P['armR'][0] += 1.2 * math.sin(t * 1.1) * idle
            P['armL'][0] += 1.2 * math.sin(t * 1.1 + 0.6) * idle
            P['head'][0] += 1.5 * math.sin(t * 0.7) * idle
            P['head'][1] += 3.5 * math.sin(t * 0.37) * idle
            P['body'][2] += 0.9 * math.sin(t * 0.45) * idle
            P['legA'][2] += 0.5 * math.sin(t * 0.45) * idle
            P['legB'][2] += 0.5 * math.sin(t * 0.45) * idle
        if s in ('walk', 'sprint', 'sneak', 'land', 'idle'):
            k = st['walk'] * (1.25 if s == 'sprint' else (0.7 if s == 'sneak' else 1.0))
            P['legA'][0] += sw * k
            P['legB'][0] += -sw * k
            P['armR'][0] += sw * arms * (1.35 if s == 'sprint' else 0.9)
            P['armL'][0] += -sw * arms * (1.35 if s == 'sprint' else 0.9)
            P['body'][1] += cw * 2.5 * lean * min(1.0, limb)
            P['head'][1] -= cw * 1.5 * lean * min(1.0, limb)
            torso[1] += abs(cw) * (0.022 if s == 'sprint' else 0.012) * min(1.0, limb) * lean
            if s == 'sprint':
                P['body'][0] += 9.0 * lean
                P['head'][0] -= 7.0 * lean * st['head']        # (the head stays level as the body leans)
                P['armR'][2] += -4.0 * arms
                P['armL'][2] += 4.0 * arms
                P['armR'][0] += 12.0 * arms * lean              # (elbows back: the arms pump higher)
                P['armL'][0] += 12.0 * arms * lean
            elif s == 'walk':
                P['body'][0] += 2.0 * lean * min(1.0, limb)
                P['head'][0] -= 1.5 * lean * min(1.0, limb)
        if s == 'sneak':
            P['body'][0] += 24.0
            P['head'][0] -= 24.0
            P['armR'][0] += 18.0
            P['armL'][0] += 18.0
            torso[1] -= 0.02
            torso[2] -= 0.05
        elif s == 'land':
            u = clamp(self.land_t / 0.28, 0.0, 1.0)
            env = (1 - u) ** 2 * self.land_amt * st['land']
            P['body'][0] += 14.0 * env
            P['head'][0] -= 6.0 * env
            y -= 0.09 * env
            P['legA'][0] += 10.0 * env
            P['legB'][0] += 10.0 * env
            P['armR'][0] += 14.0 * env
            P['armL'][0] += 14.0 * env
            P['armR'][2] += -8.0 * env
            P['armL'][2] += 8.0 * env
        elif s == 'jump':
            j = st['jump']
            P['legA'][0] += -12.0 * j
            P['legB'][0] += 8.0 * j
            P['armR'][2] += -10.0 * j
            P['armL'][2] += 10.0 * j
            P['armR'][0] += -20.0 * j
            P['armL'][0] += -20.0 * j
            P['body'][0] += 4.0 * j
        elif s == 'rise':
            j = st['jump']
            P['armR'][0] += -28.0 * j
            P['armL'][0] += -28.0 * j
            P['armR'][2] += -14.0 * j
            P['armL'][2] += 14.0 * j
            P['legA'][0] += 14.0 * j
            P['legB'][0] += -20.0 * j
            P['body'][0] += 3.0 * j
        elif s == 'apex':
            j = st['jump']
            P['armR'][0] += -12.0 * j
            P['armL'][0] += -12.0 * j
            P['armR'][2] += -18.0 * j
            P['armL'][2] += 18.0 * j
            P['legA'][0] += 9.0 * j
            P['legB'][0] += -9.0 * j
        elif s == 'fall':
            f = clamp((-vy - 1.6) / 9.0, 0.0, 1.0)
            j = st['jump']
            P['armR'][2] += -(22.0 + 55.0 * f) * j
            P['armL'][2] += (22.0 + 55.0 * f) * j
            P['armR'][0] += -(8.0 + 22.0 * f) * j
            P['armL'][0] += -(8.0 + 22.0 * f) * j
            P['legA'][0] += 22.0 * f * j
            P['legB'][0] += -10.0 * f * j
            P['legA'][2] += 4.0 * f * j
            P['legB'][2] += -4.0 * f * j
            P['body'][0] += -6.0 * f * j * st['lean']
            P['head'][0] += 10.0 * f * j
            P['body'][2] += 2.5 * math.sin(self.air_t * 5.0) * f * j
        elif s == 'swim':
            self.swim_t += inp['dt'] * (5.0 if speed > 0.8 else 2.2)
            w = self.swim_t
            fwd = inp.get('fwd', speed)
            side = inp.get('side', 0.0)
            if speed > 0.8 and abs(fwd) >= abs(side) * 0.8:    # swimming along: a crawl, lying forward
                P['body'][0] += 55.0
                P['head'][0] -= 45.0
                torso[2] -= 0.12
                torso[1] -= 0.05
                P['armR'][0] += math.sin(w) * 110.0 - 20.0
                P['armL'][0] += math.sin(w + math.pi) * 110.0 - 20.0
                P['armR'][2] += -12.0
                P['armL'][2] += 12.0
                P['legA'][0] += math.sin(w * 2.0) * 22.0
                P['legB'][0] += -math.sin(w * 2.0) * 22.0
            elif speed > 0.8:                                  # sideways: lean into it, one arm reaching
                sgn = 1.0 if side > 0 else -1.0
                P['body'][2] += -22.0 * sgn
                P['head'][2] += 10.0 * sgn
                P['armR'][2] += -40.0 - (30.0 if sgn > 0 else 0.0) + math.sin(w) * 15.0
                P['armL'][2] += 40.0 + (30.0 if sgn < 0 else 0.0) - math.sin(w) * 15.0
                P['legA'][0] += math.sin(w * 2.0) * 18.0
                P['legB'][0] += -math.sin(w * 2.0) * 18.0
            else:                                              # treading water, going up or down
                P['body'][0] += 8.0
                P['armR'][2] += -(38.0 + 14.0 * math.sin(w))
                P['armL'][2] += 38.0 + 14.0 * math.sin(w)
                P['legA'][0] += math.sin(w * 1.5) * 16.0
                P['legB'][0] += -math.sin(w * 1.5) * 16.0
                if vy > 0.6:                                   # pressing down to go up
                    P['armR'][0] += -35.0
                    P['armL'][0] += -35.0
                    P['armR'][2] += 20.0
                    P['armL'][2] += -20.0
                elif vy < -0.6:                                # arms up, sinking
                    P['armR'][2] += -45.0
                    P['armL'][2] += 45.0
                    P['head'][0] += 12.0
        elif s == 'climb':
            w = inp.get('y', 0.0) * 3.0
            P['armR'][0] += -(70.0 + 25.0 * math.sin(w))
            P['armL'][0] += -(70.0 + 25.0 * math.sin(w + math.pi))
            P['legA'][0] += 22.0 + 20.0 * math.sin(w + math.pi)
            P['legB'][0] += 22.0 + 20.0 * math.sin(w)
            P['body'][0] += 5.0
            torso[2] += 0.04
        elif s == 'sit':
            P['legA'] = [72.0, 10.0, 0.0]
            P['legB'] = [72.0, -10.0, 0.0]
            P['armL'][0] += 36.0
            P['armR'][0] += 36.0
        elif s == 'fly':
            P['body'][0] += clamp(speed * 2.5, 0.0, 22.0) * lean
            P['head'][0] -= clamp(speed * 2.0, 0.0, 18.0) * lean
            P['armR'][2] += -8.0 - clamp(speed, 0, 6) * 3.0
            P['armL'][2] += 8.0 + clamp(speed, 0, 6) * 3.0
            P['armR'][0] += -10.0 * lean
            P['armL'][0] += -10.0 * lean
            P['legA'][0] += 4.0
            P['legB'][0] += -4.0
        # blocking: the sword across the body, or the shield up in front
        if inp.get('blocking'):
            if inp.get('block_kind') == 'shield':
                P['armR'] = [62.0, 28.0, -12.0]
                P['body'][1] += -8.0
                P['head'][0] += 6.0
                torso[2] -= 0.01
            else:
                P['armR'][0] = P['armR'][0] * 0.5 + 54.0
                P['armR'][1] += BLOCK_ARM_IN
        return P, y, torso

    # -- the layers on top ---------------------------------------------------------------------
    def attack_layer(self, inp, st, P):
        f = clamp(inp.get('swing', 0.0), 0.0, 1.0)
        if f <= 0.0:
            return
        wc, combo, crit, spr = swing_kind_unpack(inp.get('swing_kind', 0))
        strike, wind = swing_envelope(f, wc)
        k = st['attack'] * (1.15 if crit else 1.0) * (1.08 if spr else 1.0)
        name = WEAPON_CLASSES[wc] if wc < len(WEAPON_CLASSES) else 'item'
        ar = P['armR']
        if name == 'sword':
            if combo == 0:                                     # a diagonal slash
                ar[0] += (92.0 * strike - 18.0 * wind) * k
                ar[1] += -32.0 * strike * k
                ar[2] += 18.0 * strike * k
                P['body'][1] += -12.0 * strike * k
            elif combo == 1:                                   # the return slash the other way
                ar[0] += (86.0 * strike - 15.0 * wind) * k
                ar[1] += 28.0 * strike * k
                ar[2] += -20.0 * strike * k
                P['body'][1] += 12.0 * strike * k
            elif combo == 2:                                   # a thrust
                ar[0] += (96.0 * strike - 20.0 * wind) * k
                ar[1] += -6.0 * strike * k
                P['body'][1] += -9.0 * strike * k
                P['body'][0] += 5.0 * strike * k
                P['torso'][2] -= 0.05 * strike * k
            else:                                              # an overhead finisher
                ar[0] += (128.0 * strike - 30.0 * wind) * k
                ar[2] += 8.0 * strike * k
                P['body'][0] += 8.0 * strike * k
                P['head'][0] += 6.0 * strike * k
        elif name == 'axe':
            ar[0] += (-40.0 * wind + 132.0 * strike) * k
            ar[2] += (14.0 * wind + 10.0 * strike) * k
            ar[1] += -10.0 * strike * k
            P['body'][0] += (-4.0 * wind + 11.0 * strike) * k
            P['head'][0] += 7.0 * strike * k
            P['body'][1] += -10.0 * strike * k
        elif name == 'mace':
            # the arm heaves up over the shoulder (through the front), then comes down with the body behind it
            if f < 0.28:
                arm = 200.0 * wind
            elif f < 0.5:
                arm = 200.0 - 130.0 * strike
            elif f < 0.78:
                arm = 70.0 - 260.0 * (strike - 1.0)
            else:
                arm = 70.0 * strike
            ar[0] += arm * k
            ar[2] += (18.0 * wind - 6.0 * strike) * k
            P['body'][0] += (-10.0 * wind + 16.0 * strike) * k
            P['head'][0] += 9.0 * strike * k
            P['body'][1] += -8.0 * strike * k
            P['torso'][1] -= 0.045 * strike * k
            P['legA'][0] += 8.0 * strike * k
            P['legB'][0] += -8.0 * strike * k
        elif name == 'shield':
            ar[0] += 48.0 * strike * k
            ar[2] += 16.0 * strike * k
            P['body'][1] += -10.0 * strike * k
            P['torso'][2] -= 0.04 * strike * k
        elif name == 'fist':
            ar[0] += (78.0 * strike - 12.0 * wind) * k
            ar[1] += -16.0 * strike * k
            P['body'][1] += -7.0 * strike * k
        else:                                                  # tools, items: the classic mining swing
            ar[0] += (80.0 * strike - 10.0 * wind) * k
            ar[1] += -22.0 * strike * k
            P['body'][1] += -6.0 * strike * k
        P['armL'][0] += -0.25 * (ar[0] - P['armL'][0]) * strike * 0.5
        P['armL'][2] += 4.0 * strike * k
        if crit:
            P['torso'][1] -= 0.03 * strike
            P['body'][0] += 4.0 * strike

    def hit_layer(self, inp, st, P):
        """A short flinch away from where a hit came from (the knock's direction relative to the facing)."""
        seq = inp.get('hit_seq', 0)
        if seq != self.hit_seq:
            self.hit_seq = seq
            self.hit_t = 0.4
            self.hit_dir = inp.get('hit_dir')
        if self.hit_t <= 0.0:
            return
        self.hit_t = max(0.0, self.hit_t - inp['dt'])
        u = 1.0 - self.hit_t / 0.4
        env = math.sin(u * math.pi) ** 0.7 * st['hit']
        if self.hit_dir is None:
            P['body'][0] += 5.0 * env
            P['head'][0] += -6.0 * env
            P['armR'][2] += -8.0 * env
            P['armL'][2] += 8.0 * env
            return
        a = math.radians(self.hit_dir)
        kf, kr = math.cos(a), math.sin(a)                      # pushed: forward, to the right
        P['body'][0] += 12.0 * kf * env
        P['head'][0] += -9.0 * kf * env
        P['body'][2] += -14.0 * kr * env
        P['head'][2] += -5.0 * kr * env
        P['head'][1] += 10.0 * kr * env
        if kr > 0:
            P['armL'][2] += 28.0 * kr * env
        else:
            P['armR'][2] += 28.0 * kr * env
        P['torso'][0] += 0.02 * kr * env
        P['torso'][2] += 0.025 * kf * env

    # -- a frame --------------------------------------------------------------------------------
    def update(self, dt, inp):
        dt = clamp(dt, 0.0005, 0.1)
        inp['dt'] = dt
        self.t += dt
        st = ANIM_PARAMS.get(inp.get('style') or 'pvp', ANIM_PARAMS['pvp'])
        # speed and vertical speed: given, or worked out from where the entity was last frame
        x, y, z = inp.get('x', 0.0), inp.get('y', 0.0), inp.get('z', 0.0)
        if self.last_pos is not None and inp.get('vx') is None:
            dx, dz = x - self.last_pos[0], z - self.last_pos[2]
            if abs(dx) < 8 and abs(dz) < 8:
                sp = math.hypot(dx, dz) / dt
                yr = math.radians(inp.get('yaw', 0.0))
                fx, fz = math.sin(yr), -math.cos(yr)
                inp['fwd'] = (dx * fx + dz * fz) / dt
                inp['side'] = (dx * fz - dz * fx) / dt
            else:
                sp = self.speed
            if abs(y - self.last_pos[1]) < 8:
                self.est_vy += ((y - self.last_pos[1]) / dt - self.est_vy) * min(1.0, dt * 20.0)
        else:
            sp = math.hypot(inp.get('vx') or 0.0, inp.get('vz') or 0.0)
            yr = math.radians(inp.get('yaw', 0.0))
            fx, fz = math.sin(yr), -math.cos(yr)
            inp['fwd'] = (inp.get('vx') or 0.0) * fx + (inp.get('vz') or 0.0) * fz
            inp['side'] = (inp.get('vx') or 0.0) * fz - (inp.get('vz') or 0.0) * fx
        self.last_pos = (x, y, z)
        self.speed += (sp - self.speed) * min(1.0, dt * 12.0)
        speed = self.speed if inp.get('vx') is None else sp
        vy = inp['vy'] if inp.get('vy') is not None else self.est_vy
        # in the air / landed
        if inp['on_ground']:
            if not self.was_ground:
                self.land_t = 0.0
                self.land_amt = clamp(0.2 + (-self.min_vy - 4.0) * 0.07, 0.2, 1.0)
            else:
                self.land_t += dt
            self.air_t = 0.0
            self.min_vy = 0.0
        else:
            self.air_t += dt
            self.land_t = 9.0
            self.min_vy = min(self.min_vy, vy)
        self.was_ground = bool(inp['on_ground'])
        new = self.pick_state(inp, vy, speed)
        if new != self.state:
            self.tau = self.transition_tau(self.state, new, st)
            self.state = new
            self.state_t = 0.0
        else:
            self.state_t += dt
            self.tau += (st['blend'] - self.tau) * min(1.0, dt * 3.0)
        P, ty, torso = self.locomotion(inp, st, vy, speed)
        # ease the body toward the state's pose (never a snap: the blend time is the state change's)
        k = 1.0 - math.exp(-dt / max(0.015, self.tau))
        for c in self.CHANNELS:
            cur, tgt = self.cur[c], P[c]
            for i in range(3):
                cur[i] += (tgt[i] - cur[i]) * k
        self.cur_y += (ty - self.cur_y) * k
        for i in range(3):
            self.cur_torso[i] += (torso[i] - self.cur_torso[i]) * k
        # then the layers that must answer at once: the swing, a hit, looking around
        L = {c: list(self.cur[c]) for c in self.CHANNELS}
        L['torso'] = list(self.cur_torso)
        self.attack_layer(inp, st, L)
        self.hit_layer(inp, st, L)
        L['head'][0] += -clamp(inp.get('pitch', 0.0) + inp.get('hpit', 0.0), -60.0, 60.0) * st['head'] \
            if self.state != 'swim' else -clamp(inp.get('pitch', 0.0), -60.0, 60.0) * 0.3
        L['head'][1] += -inp.get('hyaw', 0.0)
        pose = {c: tuple(L[c]) for c in self.CHANNELS}
        pose['y'] = self.cur_y
        pose['torso'] = tuple(L['torso'])
        self.pose = pose
        return pose


# ----------------------------------------------------------------------------
#  MUSIC FROM FILES: put MP3s (or WAV / WMA) in blockcraft_worlds/music and they play in the background,
#  shuffled, with a quiet gap between tracks - through Windows' own media player (MCI in winmm.dll, so there
#  is still nothing to install).  All of it runs on its own thread; the game only reads a few flags.  With
#  an empty folder the synthesized music plays as before.
# ----------------------------------------------------------------------------
MUSIC_DIR = os.path.join(SAVE_DIR, 'music')
MUSIC_EXTS = ('.mp3', '.wav', '.wma')


class MusicError(Exception):
    pass


class MciMusic:
    """Windows' media control interface: open a file, play it, ask how it is doing.  Only ever used from the
    music thread."""
    ALIAS = 'bcmusic'

    def __init__(self):
        self.mm = ctypes.windll.winmm
        self.mm.mciSendStringW.argtypes = [ctypes.c_wchar_p, ctypes.c_wchar_p, ctypes.c_uint, ctypes.c_void_p]
        self.mm.mciSendStringW.restype = wt.DWORD
        self.mm.mciGetErrorStringW.argtypes = [wt.DWORD, ctypes.c_wchar_p, ctypes.c_uint]
        self.mm.mciGetErrorStringW.restype = wt.BOOL
        self.k32 = ctypes.windll.kernel32
        self.k32.GetShortPathNameW.argtypes = [ctypes.c_wchar_p, ctypes.c_wchar_p, wt.DWORD]
        self.k32.GetShortPathNameW.restype = wt.DWORD
        self.opened = False

    def cmd(self, s, n=256):
        buf = ctypes.create_unicode_buffer(n)
        err = self.mm.mciSendStringW(s, buf, n, None)
        if err:
            eb = ctypes.create_unicode_buffer(256)
            self.mm.mciGetErrorStringW(err, eb, 256)
            raise MusicError(eb.value or ('media error %d' % err))
        return buf.value

    def short_path(self, path):
        """The old 8.3 form of a path when Windows has one: the media player is happiest with plain names."""
        try:
            n = self.k32.GetShortPathNameW(path, None, 0)
            if n:
                buf = ctypes.create_unicode_buffer(n + 1)
                if self.k32.GetShortPathNameW(path, buf, n + 1) and buf.value:
                    return buf.value
        except Exception:
            pass
        return path

    def open(self, path):
        if self.opened:
            self.close()
        p = self.short_path(path).replace('"', '')
        try:
            self.cmd('open "%s" type mpegvideo alias %s' % (p, self.ALIAS))
        except MusicError:
            self.cmd('open "%s" alias %s' % (p, self.ALIAS))
        self.opened = True

    def play(self):
        self.cmd('play %s from 0' % self.ALIAS)

    def pause(self):
        self.cmd('pause %s' % self.ALIAS)

    def resume(self):
        self.cmd('resume %s' % self.ALIAS)

    def volume(self, v):
        self.cmd('setaudio %s volume to %d' % (self.ALIAS, int(clamp(v, 0.0, 1.0) * 1000)))

    def mode(self):
        return self.cmd('status %s mode' % self.ALIAS).strip().lower()

    def length_ms(self):
        try:
            return int(self.cmd('status %s length' % self.ALIAS))
        except (MusicError, ValueError):
            return 0

    def position_ms(self):
        try:
            return int(self.cmd('status %s position' % self.ALIAS))
        except (MusicError, ValueError):
            return 0

    def close(self):
        self.opened = False
        try:
            self.cmd('close %s' % self.ALIAS)
        except MusicError:
            pass


def music_title(path):
    """'Aria_Math_-_C418.mp3' -> 'Aria Math - C418'."""
    s = os.path.splitext(os.path.basename(path))[0]
    s = re.sub(r'^[0-9a-f]{8}-', '', s)
    s = re.sub(r'^\d{1,3}[ ._-]+', '', s)                     # a track number
    s = s.replace('_', ' ')
    s = re.sub(r'\s+', ' ', s).strip()
    return s[:60] or 'Untitled'


class MusicPlayer:
    GAP = (45.0, 150.0)                   # seconds of quiet between tracks
    FIRST_GAP = (4.0, 12.0)
    MUSIC_LEVEL = 0.8                     # music sits a little under the effects

    def __init__(self, folder=None, backend=None, threaded=True):
        self.folder = folder or MUSIC_DIR
        self.tracks = []                  # [(path, title)]
        self.bag = []                     # the shuffle: what is left to play before every track has had a turn
        self.last_path = None
        self.enabled = True
        self.volume = 1.0
        self.state = 'idle'               # idle | opening | playing | paused
        self.current = None               # the title playing
        self.gap = random.uniform(*self.FIRST_GAP)
        self.events = deque()             # ('started', title) for the game to show
        self.errors = {}                  # path -> failures (a file that fails twice is dropped)
        self.paused_for = False           # paused while a jukebox record plays
        self.cmds = deque()
        self.cv = threading.Condition()
        self.quit = False
        self.thread = None
        self.backend = backend
        if backend is None and IS_WIN:
            try:
                self.backend = MciMusic()
            except Exception:
                self.backend = None
        try:
            os.makedirs(self.folder, exist_ok=True)
        except OSError:
            pass
        self.scan()
        if threaded and self.backend is not None:
            self.thread = threading.Thread(target=self._loop, name='music', daemon=True)
            self.thread.start()

    # -- the folder ----------------------------------------------------------------------------
    def scan(self):
        found = []
        try:
            names = sorted(os.listdir(self.folder), key=lambda n: n.lower())
        except OSError:
            names = []
        for n in names:
            if n.lower().endswith(MUSIC_EXTS) and not n.startswith('.'):
                p = os.path.join(self.folder, n)
                if os.path.isfile(p) and self.errors.get(p, 0) < 2:
                    found.append((p, music_title(p)))
        self.tracks = found
        self.bag = [t for t in self.bag if t in found]
        return found

    def available(self):
        return self.backend is not None and bool(self.tracks)

    # -- the game's side -----------------------------------------------------------------------
    def update(self, dt, jukebox=False):
        """Once a frame: start the next track when the quiet gap is over; give way to a jukebox record."""
        if not self.available():
            return
        if jukebox:
            if self.state == 'playing' and not self.paused_for:
                self.paused_for = True
                self.send(('pause',))
            return
        if self.paused_for:
            self.paused_for = False
            if self.state == 'paused':
                self.send(('resume',))
        if not self.enabled:
            if self.state != 'idle':
                self.send(('stop',))
            return
        if self.state == 'idle':
            self.gap -= dt
            if self.gap <= 0.0:
                self.start_next()

    def pick(self):
        if not self.bag:
            self.bag = list(self.tracks)
            random.shuffle(self.bag)
            if len(self.bag) > 1 and self.bag[0][0] == self.last_path:
                self.bag.append(self.bag.pop(0))              # (not the same track twice running)
        if not self.bag:
            return None
        return self.bag.pop(0)

    def start_next(self):
        t = self.pick()
        if t is None:
            return
        self.last_path = t[0]
        self.state = 'opening'
        self.current = t[1]
        self.send(('open', t[0], t[1]))

    def skip(self):
        """On to the next track (or, when quiet, straight to one)."""
        if self.state != 'idle':
            self.send(('stop', 'skip'))
        else:
            self.gap = 0.0

    def stop(self):
        if self.state != 'idle':
            self.send(('stop',))
        self.gap = random.uniform(*self.GAP)

    def set_enabled(self, on):
        self.enabled = bool(on)
        if self.enabled and self.state == 'idle':
            self.gap = min(self.gap, random.uniform(*self.FIRST_GAP))

    def set_volume(self, v):
        v = clamp(float(v), 0.0, 1.0)
        if abs(v - self.volume) > 1e-6:
            self.volume = v
            if self.state in ('playing', 'paused', 'opening'):
                self.send(('volume',))

    def now_playing(self):
        return self.current if self.state in ('playing', 'opening', 'paused') else None

    def send(self, cmd):
        with self.cv:
            self.cmds.append(cmd)
            self.cv.notify()

    def close(self):
        self.quit = True
        self.send(('quit',))
        if self.thread is not None:
            self.thread.join(2.0)
        elif self.backend is not None:
            self._do(('quit',))

    # -- the music thread ----------------------------------------------------------------------
    def _loop(self):
        while not self.quit:
            with self.cv:
                if not self.cmds:
                    self.cv.wait(0.5)
                cmds = list(self.cmds)
                self.cmds.clear()
            for c in cmds:
                self._do(c)
            if self.state == 'playing':
                self._poll()

    def work(self):
        """What the thread does, for a game without one (tests)."""
        with self.cv:
            cmds = list(self.cmds)
            self.cmds.clear()
        for c in cmds:
            self._do(c)
        if self.state == 'playing':
            self._poll()

    def _do(self, c):
        b = self.backend
        kind = c[0]
        try:
            if kind == 'open':
                path, title = c[1], c[2]
                try:
                    b.open(path)
                    b.volume(self.volume * self.MUSIC_LEVEL)
                    b.play()
                except Exception:
                    self.errors[path] = self.errors.get(path, 0) + 1
                    try:
                        b.close()
                    except Exception:
                        pass
                    self.state, self.current = 'idle', None
                    self.gap = 2.0
                    self.events.append(('failed', title))
                    self.scan()
                    return
                self.state = 'playing'
                self.events.append(('started', title))
            elif kind == 'pause':
                if self.state == 'playing':
                    b.pause()
                    self.state = 'paused'
            elif kind == 'resume':
                if self.state == 'paused':
                    b.resume()
                    self.state = 'playing'
            elif kind == 'volume':
                if self.state in ('playing', 'paused'):
                    b.volume(self.volume * self.MUSIC_LEVEL)
            elif kind == 'stop':
                if self.state != 'idle':
                    b.close()
                self.state, self.current = 'idle', None
                self.gap = 0.5 if len(c) > 1 and c[1] == 'skip' else random.uniform(*self.GAP)
            elif kind == 'quit':
                if self.state != 'idle':
                    b.close()
                self.state, self.current = 'idle', None
        except Exception:
            traceback.print_exc()
            try:
                b.close()
            except Exception:
                pass
            self.state, self.current = 'idle', None
            self.gap = 5.0

    def _poll(self):
        """Has the track ended?  (The player reports 'stopped' once it has played out.)"""
        b = self.backend
        try:
            mode = b.mode()
        except Exception:
            mode = 'stopped'
        if mode in ('stopped', 'not ready', ''):
            if mode == 'stopped':
                ln, pos = b.length_ms(), b.position_ms()
                if ln and pos < ln - 1500 and pos < 500:
                    return                                    # (just opened: not started yet)
            try:
                b.close()
            except Exception:
                pass
            self.state, self.current = 'idle', None
            self.gap = random.uniform(*self.GAP)


def upload_list(old, pos, uv, col):
    """Vertex arrays (bytes) -> an OpenGL display list (returns 0 when empty)."""
    n = len(pos) // 12
    if not n:
        if old:
            glDeleteLists(old, 1)
        return 0
    lst = old or glGenLists(1)
    pa = (ctypes.c_char * len(pos)).from_buffer_copy(pos)
    ua = (ctypes.c_char * len(uv)).from_buffer_copy(uv)
    ca = (ctypes.c_char * len(col)).from_buffer_copy(col)
    glEnableClientState(GL_VERTEX_ARRAY)
    glEnableClientState(GL_TEXTURE_COORD_ARRAY)
    glEnableClientState(GL_COLOR_ARRAY)
    glVertexPointer(3, GL_FLOAT, 0, pa)
    glTexCoordPointer(2, GL_FLOAT, 0, ua)
    glColorPointer(4, GL_UNSIGNED_BYTE, 0, ca)
    glNewList(lst, GL_COMPILE)
    glDrawArrays(GL_QUADS, 0, n)
    glEndList()
    glDisableClientState(GL_VERTEX_ARRAY)
    glDisableClientState(GL_TEXTURE_COORD_ARRAY)
    glDisableClientState(GL_COLOR_ARRAY)
    return lst


DEFAULT_OPTS = dict(fabulous=False, pack='default', skin=0, rbook=False, rbcraft=False, render=8, fov=70, sens=0.15, smooth=True, fancy=True, clouds=True, vsync=True, volume=1.0,
                    music=True, bob=True, gui=0, scale=0, name='', particles=True, bright=2.0, keys={}, invert=False,
                    cskin='', ccape='', anim='pvp')

# every action that can be rebound: (action, label on the Controls screen, default key or mouse button)
KEY_ACTIONS = [
    ('forward', 'Forward', 'w'), ('back', 'Back', 's'), ('left', 'Left', 'a'), ('right', 'Right', 'd'),
    ('jump', 'Jump', 'space'), ('sneak', 'Sneak', 'shift_l'), ('sprint', 'Sprint', 'control_l'),
    ('attack', 'Attack', 'mouse1'), ('use', 'Use Item', 'mouse3'), ('pick', 'Pick Block', 'mouse2'),
    ('inventory', 'Inventory', 'e'), ('drop', 'Drop Item', 'q'), ('chat', 'Chat', 't'), ('command', 'Command', 'slash'),
    ('hud', 'Hide HUD', 'f1'), ('smooth', 'Smooth Light', 'f2'), ('debug', 'Debug Info', 'f3'),
    ('camera', 'Camera View', 'f5'),
] + [('hotbar%d' % i, 'Hotbar %d' % i, str(i)) for i in range(1, 10)]
DEFAULT_KEYS = {a: k for a, _, k in KEY_ACTIONS}
_KEY_NAMES = {'space': 'Space', 'shift_l': 'Shift', 'control_l': 'Ctrl', 'alt_l': 'Alt', 'mouse1': 'Left Click',
              'mouse2': 'Middle Click', 'mouse3': 'Right Click', 'slash': '/', 'return': 'Enter', 'tab': 'Tab',
              'caps_lock': 'Caps Lock', 'backspace': 'Backspace', 'comma': ',', 'period': '.', 'minus': '-',
              'equal': '=', 'semicolon': ';', 'apostrophe': "'", 'bracketleft': '[', 'bracketright': ']',
              'backslash': '\\', 'grave': '`', 'up': 'Up', 'down': 'Down', 'left': 'Left', 'right': 'Right',
              'prior': 'Page Up', 'next': 'Page Down', 'home': 'Home', 'end': 'End', 'insert': 'Insert',
              'delete': 'Delete'}
_KEY_ALIAS = {'shift_r': 'shift_l', 'control_r': 'control_l', 'alt_r': 'alt_l', 'kp_enter': 'return'}


def key_label(k):
    if k in _KEY_NAMES:
        return _KEY_NAMES[k]
    if k.startswith('mouse'):
        return 'Mouse %s' % k[5:]
    if k.startswith('kp_'):
        return 'Num %s' % k[3:].title()
    return k.upper() if len(k) <= 3 else k.replace('_', ' ').title()


# ----------------------------------------------------------------------------
#  THE GAME
# ----------------------------------------------------------------------------
class Game:
    def __init__(self):
        if IS_WIN:
            try:
                ctypes.windll.shcore.SetProcessDpiAwareness(1)
            except Exception:
                pass
        import tkinter as tk
        self.tk = tk
        self.root = tk.Tk()
        self.root.title('Blockcraft')
        self.root.configure(bg='black')
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        w, h = min(1280, int(sw * 0.8)), min(760, int(sh * 0.8))
        self.root.geometry('%dx%d+%d+%d' % (w, h, (sw - w) // 2, max(0, (sh - h) // 2 - 30)))
        self.root.minsize(640, 400)
        self.frame = tk.Frame(self.root, bg='black', highlightthickness=0, bd=0, takefocus=1)
        self.frame.pack(fill='both', expand=True)
        self.root.update()
        self.ctx = GLContext(self.frame.winfo_id(), software=bool(os.environ.get('BLOCKCRAFT_SOFTWARE')))
        self.software = self.ctx.software
        self.W, self.H = self.frame.winfo_width(), self.frame.winfo_height()
        try:                                                  # (the texture pack saved in the options)
            with open(OPTIONS_FILE, 'r', encoding='utf-8') as f:
                pk = json.load(f).get('pack', 'default')
        except Exception:
            pk = 'default'
        self.atlas_pack = pk if pk in PACK_KEYS else 'default'
        self.atlas_data = build_atlas(self.atlas_pack)        # (kept: item models and map colours come from it)
        self.tex = make_texture(self.atlas_data, ATLAS, ATLAS)
        self.water_frames = pack_frames(liquid_frames('water'), 'water', self.atlas_pack)
        self.lava_frames = pack_frames(liquid_frames('lava'), 'lava', self.atlas_pack)
        self.fire_frames = pack_frames(fire_frames(32), 'fire', self.atlas_pack)
        self.portal_frames = pack_frames(portal_frames(32), 'portal', self.atlas_pack)
        self.anim_t = 0.0
        self.font = PixelFont(9, 'Tahoma')
        self.font.upload()
        self.vignette = self.make_vignette()
        self.cloud_tex = self.make_clouds()
        self.rain_tex, self.snow_tex, self.aura_tex = self.make_weather_tex()
        self.paint_tex = self.make_paintings()
        self.opts = dict(DEFAULT_OPTS)
        self.opts['name'] = 'Player%d' % random.randint(10, 99)
        self.load_options()
        self.library = CosmeticLibrary()                   # your saved skins and capes (and peers' pictures)
        self.library.load()
        self.cos_tex = {}                                  # (kind, hash) -> GL texture
        self.cos_tex_used = {}
        self.player_cos = {}                               # LAN roster: name -> {'skin': ..., 'cape': ...}
        self.my_cos = None
        self.refresh_my_cos()
        self.ui_hov, self.ui_scrolls, self.prev_cam = {}, {}, {}        # the dark menus' state
        self.ui_lock, self.ui_anim, self.ui_alpha, self.ui_tip_text = False, None, 1.0, None
        self.cos_tab, self.cos_back, self.cos_sel, self.cos_sel_cape = 'skins', 'title', None, None
        self.cos_import, self.cos_err, self.cos_rename, self.cos_confirm = None, None, None, None
        self.cos_pulse, self.cos_click_t = None, 0.0
        self.cos_editor, self.edit_leave_t, self.ed_pick = None, 0.0, None
        self.frame_dt = 0.016
        self.cos_gc_t = 0.0
        if self.opts.get('pack', 'default') != self.atlas_pack:
            self.set_pack(self.opts['pack'])
        if self.opts.get('fabulous'):
            self.apply_filter()
        self.opts['keys'] = {a: k for a, k in dict(self.opts.get('keys') or {}).items()
                             if a in DEFAULT_KEYS and isinstance(k, str) and k}
        if self.software and not os.path.exists(OPTIONS_FILE):
            self.opts.update(render=5, smooth=False, fancy=False, clouds=False)
        self.ctx.set_vsync(self.opts['vsync'])
        set_brightness(self.bright_g())
        self.workers = Workers()
        self.audio = Audio()
        self.audio.volume = self.opts['volume']
        self.audio.music_on = self.opts['music']
        self.music = MusicPlayer()                         # MP3s in blockcraft_worlds/music, if any
        self.music.set_enabled(self.opts['music'])
        self.music.set_volume(self.opts['volume'])
        self.sound_job = self.workers.submit(synth_all_sounds)
        self.music_jobs = [self.workers.submit(compose_music, s) for s in (random.randrange(1 << 30), random.randrange(1 << 30))]
        self.gs = 2
        # input
        self.keys = set()
        self.mx = self.my = 0
        self.clicks = []
        self.lmb = self.rmb = self.mmb = False
        self.mbuttons = set()
        self.rebinding = None
        self.ctrl_scroll = 0
        self.lmb_down_t = 0.0
        self.wheel = 0
        self.typed = []
        self.grab = False
        self.grab_center = (0, 0)
        self.focus = None
        self.fields = {'name': self.opts['name'], 'seed': '', 'wname': 'New World', 'ip': '', 'add': '', 'chat': '',
                       'csearch': '', 'rename': '', 'cosname': '', 'edname': '', 'hex': ''}
        self.scroll = 0
        self.running = True
        self.t = 0.0
        self.fps = 0.0
        self.fps_n = 0
        self.fps_t = 0.0
        self.frame_ms = 0.0
        self.msg = ''
        self.msg_t = 0.0
        self.scene = 'title'
        self.overlay = None
        self.world = None
        self.title_world = None
        self.net = None
        self.remote = None
        self.reset_session()
        self.splash = random.choice(['Now in 3D!', 'One file!', 'No installs!', 'Made in Python!', 'Beta forever!',
                                     'Punch trees!', 'Also try UNO!', 'Uses every core!', 'Biomes!', 'Boats!',
                                     'Now with the Nether!', 'Ask Leo!', 'Hot in here!'])
        self.root.protocol('WM_DELETE_WINDOW', self.on_close)
        self.frame.bind('<Configure>', self.on_resize)
        self.frame.bind('<Motion>', self.on_motion)
        self.frame.bind('<ButtonPress>', self.on_press)
        self.frame.bind('<ButtonRelease>', self.on_release)
        self.root.bind('<MouseWheel>', self.on_wheel)
        self.root.bind('<KeyPress>', self.on_key)
        self.root.bind('<KeyRelease>', self.on_keyup)
        self.root.bind('<FocusOut>', self.on_focus_out)
        self.frame.focus_set()
        self.on_resize()
        self.install_drop_target()
        gc.freeze()

    # -- setup helpers ------------------------------------------------------------
    def make_vignette(self):
        n = 128
        buf = bytearray(n * n * 4)
        for y in range(n):
            for x in range(n):
                d = math.hypot((x - n / 2) / (n / 2), (y - n / 2) / (n / 2))
                a = int(clamp((d - 0.55) * 1.4, 0, 1) ** 1.6 * 150)
                buf[(y * n + x) * 4 + 3] = a
        return make_texture(bytes(buf), n, n, linear=True)

    def make_clouds(self):
        n = 128
        p = Perlin(4)
        buf = bytearray(n * n * 4)
        for y in range(n):
            for x in range(n):
                v = p.n2(x / 9.0, y / 9.0) + 0.5 * p.n2(x / 4.0 + 50, y / 4.0)
                if v > 0.18:
                    buf[(y * n + x) * 4:(y * n + x) * 4 + 4] = b'\xff\xff\xff\xd0'
        tid = make_texture(bytes(buf), n, n)
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT)
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT)
        return tid

    def make_paintings(self):
        """All the paintings, drawn into one 256 x 256 texture (16 pixels to a block), each in a wooden frame."""
        R = random.Random(505)
        W = 256
        buf = bytearray(W * W * 4)

        def put(x, y, c):
            if 0 <= x < W and 0 <= y < W:
                j = (y * W + x) * 4
                buf[j:j + 4] = bytes((clamp(int(c[0]), 0, 255), clamp(int(c[1]), 0, 255), clamp(int(c[2]), 0, 255), 255))

        def lerpc(a, b, t):
            return tuple(a[i] + (b[i] - a[i]) * t for i in range(3))
        for name, pw, ph, u, v in PAINTINGS:
            w_, h_ = pw * 16, ph * 16
            for y in range(h_):
                for x in range(w_):
                    fx, fy = x / float(w_), y / float(h_)
                    c = (120, 120, 120)
                    if name in ('Sea', 'Storm'):
                        sky = lerpc((70, 110, 180), (160, 190, 230), fy * 2) if name == 'Sea' else \
                            lerpc((40, 45, 60), (90, 95, 110), fy * 2)
                        wave = 0.55 + 0.04 * math.sin(fx * 25 + (3 if name == 'Storm' else 0))
                        c = sky if fy < wave else lerpc((30, 80, 150), (15, 40, 90), fy)
                        if name == 'Storm' and fy < 0.45 and abs(fx - 0.6 - 0.1 * math.sin(fy * 30)) < 0.012:
                            c = (255, 255, 230)                          # lightning
                    elif name in ('Sunset', 'Desert'):
                        c = lerpc((250, 150, 60), (120, 60, 120), fy * 1.6) if fy < 0.6 else \
                            ((200, 170, 100) if name == 'Desert' else (40, 30, 50))
                        if (fx - 0.5) ** 2 * 4 + (fy - 0.55) ** 2 * 16 < 0.05:
                            c = (255, 220, 120)
                        if name == 'Desert' and fy > 0.35 and abs(fx - 0.25) < 0.02:
                            c = (60, 130, 50)                            # a cactus
                    elif name in ('Hills', 'Mountain', 'Village', 'Castle', 'Tower', 'Tree'):
                        c = lerpc((120, 170, 235), (200, 225, 250), fy * 1.5)
                        hill = 0.62 + 0.12 * math.sin(fx * 7 + 1) + 0.05 * math.sin(fx * 19)
                        if name == 'Mountain':
                            hill = 0.35 + abs(fx - 0.5) * 1.1
                            if fy > hill:
                                c = (240, 240, 245) if fy < hill + 0.12 else (100, 100, 110)
                        elif fy > hill:
                            c = (80, 150, 60) if name != 'Castle' else (90, 120, 70)
                        if name == 'Village' and 0.5 < fy < 0.75:
                            for hx in (0.15, 0.4, 0.65, 0.85):
                                if abs(fx - hx) < 0.06:
                                    c = (170, 130, 80) if fy > 0.58 else (150, 60, 40)
                        if name == 'Castle' and 0.25 < fy and 0.3 < fx < 0.7:
                            if fy > 0.35 or int(fx * 40) % 2:
                                c = (150, 150, 155)
                        if name == 'Tower' and 0.35 < fx < 0.65 and fy > 0.2:
                            c = (140, 135, 130) if int(fy * 20) % 3 else (110, 105, 100)
                        if name == 'Tree':
                            if (fx - 0.5) ** 2 + (fy - 0.38) ** 2 * 0.3 < 0.06:
                                c = (50, 120, 40)
                            elif abs(fx - 0.5) < 0.06 and fy > 0.4:
                                c = (100, 70, 40)
                    elif name in ('Night Sky', 'Moon', 'The End'):
                        c = (15, 20, 45) if name != 'The End' else (20, 10, 30)
                        if R.random() < 0.03:
                            c = (255, 255, 230)
                        if name == 'Moon' and (fx - 0.5) ** 2 + (fy - 0.5) ** 2 < 0.08:
                            c = (230, 230, 210)
                        if name == 'The End':
                            if fy > 0.7:
                                c = (220, 220, 160) if R.random() > 0.1 else (190, 190, 140)
                            if 0.3 < fx < 0.36 and fy > 0.25:
                                c = (30, 20, 45)                          # an obsidian pillar
                    elif name == 'Nether':
                        c = lerpc((110, 20, 20), (60, 10, 10), fy)
                        if fy > 0.75:
                            c = (230, 110, 20) if R.random() > 0.2 else (250, 180, 40)
                        if (fx - 0.3) ** 2 + (fy - 0.35) ** 2 < 0.02:
                            c = (240, 240, 240)                          # a ghast
                    elif name == 'Rings':
                        d = math.hypot(fx - 0.5, fy - 0.5)
                        c = ((230, 80, 70), (240, 200, 60), (70, 160, 220), (240, 240, 240))[int(d * 14) % 4]
                    elif name == 'Stripes':
                        c = ((200, 60, 60), (240, 240, 240), (60, 90, 200))[int(fx * 12) % 3]
                    elif name == 'Checkers':
                        c = (230, 220, 200) if (int(fx * 8) + int(fy * 8)) % 2 else (60, 45, 40)
                    elif name == 'Sun':
                        c = (120, 180, 240)
                        if (fx - 0.5) ** 2 + (fy - 0.5) ** 2 < 0.08:
                            c = (255, 220, 80)
                    elif name == 'Creeper':
                        c = (80, 170, 70) if R.random() > 0.2 else (60, 140, 55)
                        px_, py_ = int(fx * 8), int(fy * 8)
                        if (py_ in (2, 3) and px_ in (1, 2, 5, 6)) or (py_ == 4 and px_ in (3, 4)) or \
                                (py_ in (5, 6) and px_ in (2, 3, 4, 5)):
                            c = (20, 20, 20)
                    elif name == 'Flower':
                        c = (190, 220, 170)
                        if (fx - 0.5) ** 2 + (fy - 0.4) ** 2 < 0.04:
                            c = (230, 60, 80)
                        elif abs(fx - 0.5) < 0.05 and fy > 0.5:
                            c = (60, 140, 50)
                    elif name == 'Skull':
                        c = (60, 50, 50)
                        if (fx - 0.5) ** 2 + (fy - 0.42) ** 2 < 0.08 or (0.35 < fx < 0.65 and 0.55 < fy < 0.78):
                            c = (230, 225, 210)
                        if (fx - 0.38) ** 2 + (fy - 0.42) ** 2 < 0.006 or (fx - 0.62) ** 2 + (fy - 0.42) ** 2 < 0.006:
                            c = (20, 20, 20)
                    elif name == 'Heart':
                        c = (250, 210, 220)
                        hx, hy = (fx - 0.5) * 2.2, (0.45 - fy) * 2.2
                        if (hx * hx + hy * hy - 0.4) ** 3 - hx * hx * hy ** 3 < 0:
                            c = (220, 40, 60)
                    elif name == 'Mushroom':
                        c = (100, 80, 60)
                        if fy < 0.5 and (fx - 0.5) ** 2 + (fy - 0.5) ** 2 < 0.12:
                            c = (210, 40, 40) if R.random() > 0.15 else (245, 245, 245)
                        elif abs(fx - 0.5) < 0.1 and fy >= 0.5:
                            c = (235, 225, 200)
                    elif name == 'Portrait':
                        c = (60, 70, 90)
                        if (fx - 0.5) ** 2 + (fy - 0.4) ** 2 < 0.05:
                            c = (220, 180, 150)                          # a face
                        elif fy > 0.62 and abs(fx - 0.5) < 0.3:
                            c = (80, 60, 140)
                    elif name == 'Dragon':
                        c = (25, 15, 35)
                        if R.random() < 0.02:
                            c = (220, 220, 230)
                        d = abs(fy - 0.5 - 0.15 * math.sin(fx * 8)) < 0.05 + 0.1 * (1 - abs(fx - 0.5) * 2)
                        if d and 0.1 < fx < 0.9:
                            c = (40, 40, 45)
                        if (fx - 0.78) ** 2 + (fy - 0.42) ** 2 < 0.001:
                            c = (220, 80, 240)                           # its eye
                    elif name == 'Leo':
                        c = lerpc((240, 230, 200), (210, 190, 150), fy)
                        if (fx - 0.5) ** 2 + (fy - 0.4) ** 2 < 0.06:
                            c = (225, 185, 150)
                        if fy < 0.32 and (fx - 0.5) ** 2 + (fy - 0.36) ** 2 < 0.065:
                            c = (90, 60, 35)                             # hair
                        if fy > 0.62 and abs(fx - 0.5) < 0.28:
                            c = (60, 110, 200)
                        for ex_ in (0.42, 0.58):
                            if (fx - ex_) ** 2 + (fy - 0.4) ** 2 < 0.0012:
                                c = (30, 30, 30)
                    if x in (0, w_ - 1) or y in (0, h_ - 1):
                        c = (100, 70, 40)                                 # the frame
                    elif x in (1, w_ - 2) or y in (1, h_ - 2):
                        c = (140, 100, 60)
                    k = R.uniform(0.94, 1.04)
                    put(u + x, v + y, (c[0] * k, c[1] * k, c[2] * k))
        return make_texture(bytes(buf), W, W)

    def make_weather_tex(self):
        """Repeating textures: rain streaks, snowflakes, and the crackling shell of a charged creeper."""
        R = random.Random(11)
        out = []
        for kind in ('rain', 'snow', 'aura'):
            wd, ht = (32, 32) if kind == 'aura' else (64, 128)
            buf = bytearray(wd * ht * 4)
            dots = []
            if kind == 'rain':
                for _ in range(34):
                    x, y, n = R.randrange(wd), R.randrange(ht), R.randint(9, 20)
                    dots += [(x, y + k, (175, 195, 255, int(190 - 110 * k / n))) for k in range(n)]
            elif kind == 'snow':
                for _ in range(34):
                    x, y = R.randrange(wd), R.randrange(ht)
                    for dx, dy in ((0, 0), (1, 0), (0, 1), (1, 1)) if R.random() < 0.6 else ((0, 0),):
                        dots.append((x + dx, y + dy, (255, 255, 255, 235)))
            else:
                for y in range(ht):
                    for x in range(wd):
                        v = math.sin((x + y) * 0.55 + math.sin(y * 0.4) * 1.6) + 0.35 * math.sin(x * 0.9 - y * 0.3)
                        if v > 0.75:
                            dots.append((x, y, (120, 170, 255, 255)))
            for x, y, c in dots:
                j = ((y % ht) * wd + (x % wd)) * 4
                buf[j:j + 4] = bytes(c)
            tid = make_texture(bytes(buf), wd, ht)
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT)
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT)
            out.append(tid)
        return out

    def load_options(self):
        try:
            with open(OPTIONS_FILE, 'r', encoding='utf-8') as f:
                d = json.load(f)
            for k in self.opts:
                if k in d and type(d[k]) == type(self.opts[k]):
                    self.opts[k] = d[k]
        except Exception:
            pass

    def save_options(self):
        self.opts['name'] = self.fields['name'].strip()[:16] or 'Player'
        try:
            write_file_atomic(OPTIONS_FILE, json.dumps(self.opts).encode('utf-8'))
        except Exception:
            pass

    def notify(self, text, secs=3.0):
        self.msg = text
        self.msg_t = secs

    def reset_session(self):
        for k in ('duel', 'duel_saved', 'duel_count', 'duel_fight', 'sprint_lock', 'pvp_hits'):
            self.__dict__.pop(k, None)                      # (a duel ends with the game it was in)
        self.player = None
        self.entities = {}
        self.containers = {}
        self.spawners = {}
        self.maps, self.map_subs, self.map_req, self.map_texs = {}, {}, {}, {}
        self.open_cont = None
        self.cursor_stack = None
        self.craft = [None] * 9
        self.craft_w = 2
        self.time = 0.0
        self.mode = 'survival'
        self.world_name = ''
        self.world_file = None
        self.mining = None
        self.place_t = 0.0
        self.attack_t = 0.0
        self.use_t = 0.0
        self.eat_t = 0.0
        self.bow_t = 0.0
        self.spawn_t = 0.0
        self.tick_t = 0.0
        self.save_t = 0.0
        self.chat = []
        self.chat_open = False
        self.debug = False
        self.hide_hud = False
        self.third = 0
        self.last_space = 0.0
        self.last_w = 0.0
        self.step_d = 0.0
        self.bob = 0.0
        self.bob_amt = 0.0
        self.swing = 0.0
